(295128,32792,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Képzeld, az alpakák állítólag közvetlenül mögötte vannak. Ők haza ... követni.'::text,'fogják'::text,'fogják'::text,NULL::text,'Képzeld, az alpakák állítólag közvetlenül mögötte vannak. Ők haza fogják követni.'::text),
(317640,35294,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yo, ... ist das Wasser so glatt? Weil kein Wind weht.'::text,'warum'::text,'wer'::text,'wo'::text,'Yo, warum ist das Wasser so glatt? Weil kein Wind weht.'::text),
(317644,35294,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Йо, ... вода така гладка? Бо немає вітру.'::text,'чому'::text,'хто'::text,'де'::text,'Йо, чому вода така гладка? Бо немає вітру.'::text),
(317643,35294,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Oye, ¿... está el agua tan lisa? Porque no hay viento.'::text,'por qué'::text,'quién'::text,'dónde'::text,'Oye, ¿por qué está el agua tan lisa? Porque no hay viento.'::text),
(317642,35294,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yo, ... l''eau est si lisse ? Parce qu''il n''y a pas de vent.'::text,'pourquoi'::text,'qui'::text,'où'::text,'Yo, pourquoi l''eau est si lisse ? Parce qu''il n''y a pas de vent.'::text),
(317645,35294,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, su ... bu kadar pürüzsüz? Çünkü rüzgâr yok.'::text,'neden'::text,'kim'::text,'nerede'::text,'Kanka, su neden bu kadar pürüzsüz? Çünkü rüzgâr yok.'::text),
(317646,35294,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Figyu, ... ilyen sima a víz? Mert nincs szél.'::text,'miért'::text,'ki'::text,'hol'::text,'Figyu, miért ilyen sima a víz? Mert nincs szél.'::text),
(317676,35298,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie gleitet mühelos, ... das Hafenwasser glatt ist.'::text,'weil'::text,'aber'::text,'also'::text,'Sie gleitet mühelos, weil das Hafenwasser glatt ist.'::text),
(317680,35298,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона легко ковзає, ... вода в гавані гладка.'::text,'бо'::text,'але'::text,'тому'::text,'Вона легко ковзає, бо вода в гавані гладка.'::text),
(317679,35298,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ella se desliza con facilidad ... el agua del puerto está lisa.'::text,'porque'::text,'pero'::text,'así que'::text,'Ella se desliza con facilidad porque el agua del puerto está lisa.'::text),
(317678,35298,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle glisse facilement ... l''eau du port est lisse.'::text,'parce que'::text,'mais'::text,'donc'::text,'Elle glisse facilement parce que l''eau du port est lisse.'::text),
(317681,35298,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O kolayca süzülüyor ... limanın suyu pürüzsüz.'::text,'çünkü'::text,'ama'::text,'bu yüzden'::text,'O kolayca süzülüyor çünkü limanın suyu pürüzsüz.'::text),
(317682,35298,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ő könnyedén siklik, ... a kikötő vize sima.'::text,'mert'::text,'de'::text,'ezért'::text,'Ő könnyedén siklik, mert a kikötő vize sima.'::text),
(325110,36124,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Super Arbeit, klar: Er ist am Ende, also ... er umkehren.'::text,'wird'::text,'wird'::text,NULL::text,'Super Arbeit, klar: Er ist am Ende, also wird er umkehren.'::text),
(325114,36124,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чудова робота, очевидно: він у кінці, тож він ... назад.'::text,'збирається повернути'::text,'поверне'::text,NULL::text,'Чудова робота, очевидно: він у кінці, тож він збирається повернути назад.'::text),
(325113,36124,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Buen trabajo, claro: él está al final, así que ... la vuelta.'::text,'va a dar'::text,'dará'::text,NULL::text,'Buen trabajo, claro: él está al final, así que va a dar la vuelta.'::text),
(325112,36124,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Beau travail, évidemment : il est au bout, donc il ... demi-tour.'::text,'va faire'::text,'fera'::text,NULL::text,'Beau travail, évidemment : il est au bout, donc il va faire demi-tour.'::text),
(325115,36124,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Harika iş, belli ki: o sonda, bu yüzden geri ...'::text,'dönecek'::text,'dönecek'::text,NULL::text,'Harika iş, belli ki: o sonda, bu yüzden geri dönecek.'::text),
(325116,36124,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Szép munka, nyilván: ő a végén van, szóval meg ... fordulni.'::text,'fog'::text,'fog'::text,NULL::text,'Szép munka, nyilván: ő a végén van, szóval meg fog fordulni.'::text),
(308208,34246,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Parkbericht: 1 Mann ist im Teich, mit ... Jacke an.'::text,'seiner'::text,'ihrer'::text,'seiner'::text,'Parkbericht: 1 Mann ist im Teich, mit seiner Jacke an.'::text),
(308212,34246,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Звіт із парку: 1 чоловік у ставку в ... куртці.'::text,'своїй'::text,'своїй'::text,'своїй'::text,'Звіт із парку: 1 чоловік у ставку в своїй куртці.'::text),
(308211,34246,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Informe del parque: 1 hombre está en el estanque con ... chaqueta puesta.'::text,'su'::text,'su'::text,'su'::text,'Informe del parque: 1 hombre está en el estanque con su chaqueta puesta.'::text),
(308210,34246,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Rapport du parc : 1 homme est dans le bassin avec ... veste sur le dos.'::text,'sa'::text,'sa'::text,'sa'::text,'Rapport du parc : 1 homme est dans le bassin avec sa veste sur le dos.'::text),
(308213,34246,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Park raporu: 1 adam ... ceketiyle gölette.'::text,'onun'::text,'onun'::text,'onun'::text,'Park raporu: 1 adam onun ceketiyle gölette.'::text),
(308214,34246,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Parkjelentés: 1 férfi a tóban van, a ... rajta.'::text,'dzsekije'::text,'dzsekije'::text,'dzsekije'::text,'Parkjelentés: 1 férfi a tóban van, a dzsekije rajta.'::text),
(308226,34248,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Du bist in einem Park mit so ... Leuten über den Rand balanciert. Mutig!'::text,'vielen'::text,'viel'::text,'einer Menge'::text,'Du bist in einem Park mit so vielen Leuten über den Rand balanciert. Mutig!'::text),
(308230,34248,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ти пройшов по краю в парку, де було так ... людей. Сміливо!'::text,'багато'::text,'багато'::text,'багато'::text,'Ти пройшов по краю в парку, де було так багато людей. Сміливо!'::text),
(308229,34248,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tú caminaste por el borde en un parque con ... personas. ¡Qué atrevido!'::text,'tantas'::text,'tanto'::text,'un montón de'::text,'Tú caminaste por el borde en un parque con tantas personas. ¡Qué atrevido!'::text),
(308228,34248,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tu as marché sur le bord dans un parc avec ... monde. Audacieux !'::text,'tellement de'::text,'tellement de'::text,'plein de'::text,'Tu as marché sur le bord dans un parc avec tellement de monde. Audacieux !'::text),
(308231,34248,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sen o kadar ... insanın olduğu bir parkta kenarda yürüdün. Cesurca!'::text,'çok'::text,'çok'::text,'çok'::text,'Sen o kadar çok insanın olduğu bir parkta kenarda yürüdün. Cesurca!'::text),
(308232,34248,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Te egy olyan parkban sétáltál a peremen, ahol olyan ... ember volt. Merész!'::text,'sok'::text,'sok'::text,'rengeteg'::text,'Te egy olyan parkban sétáltál a peremen, ahol olyan sok ember volt. Merész!'::text),
(324570,36064,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Jedes schwarze Ding auf dem Boden ist ... Falle.'::text,'eine'::text,'die'::text,'eine'::text,'Jedes schwarze Ding auf dem Boden ist eine Falle.'::text),
(324574,36064,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Кожна чорна річ на підлозі — це ... пастка.'::text,''::text,NULL::text,NULL::text,'Кожна чорна річ на підлозі — це пастка.'::text),
(324573,36064,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Cada cosa negra del suelo es ... trampa.'::text,'una'::text,'la'::text,'una'::text,'Cada cosa negra del suelo es una trampa.'::text),
(324572,36064,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Chaque truc noir par terre est ... piège.'::text,'un'::text,'le'::text,'un'::text,'Chaque truc noir par terre est un piège.'::text),
(324575,36064,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yerdeki her siyah şey ... tuzak.'::text,'bir'::text,NULL::text,'bir'::text,'Yerdeki her siyah şey bir tuzak.'::text),
(324576,36064,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A padlón minden fekete dolog ... csapda.'::text,'egy'::text,'a'::text,'egy'::text,'A padlón minden fekete dolog egy csapda.'::text),
(324615,36069,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Zwischen den Spielzeugregalen ... eine Menge Fallen.'::text,'sind'::text,'ist'::text,'sein'::text,'Zwischen den Spielzeugregalen sind eine Menge Fallen.'::text),
(324619,36069,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Між полицями з іграшками ... багато пасток.'::text,'є'::text,'є'::text,'бути'::text,'Між полицями з іграшками є багато пасток.'::text),
(324618,36069,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... un montón de trampas entre las estanterías de juguetes.'::text,'Hay'::text,'Hay'::text,'Hay'::text,'Hay un montón de trampas entre las estanterías de juguetes.'::text),
(324617,36069,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... plein de pièges entre les rayons de jouets.'::text,'Il y a'::text,'Il y a'::text,'Il y a'::text,'Il y a plein de pièges entre les rayons de jouets.'::text),
(324620,36069,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Oyuncak rafları arasında bir sürü tuzak ...'::text,'var'::text,'var'::text,'olmak'::text,'Oyuncak rafları arasında bir sürü tuzak var.'::text),
(324621,36069,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A játékos polcok között rengeteg csapda ...'::text,'van'::text,'van'::text,'lenni'::text,'A játékos polcok között rengeteg csapda van.'::text),
(319503,35501,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er ... von Block zu Block über das grüne Wasser.'::text,'steigt'::text,'steigen'::text,'steigend'::text,'Er steigt von Block zu Block über das grüne Wasser.'::text),
(319507,35501,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він ... з блока на блок над зеленою водою.'::text,'переступає'::text,'переступати'::text,'переступаючи'::text,'Він переступає з блока на блок над зеленою водою.'::text),
(319506,35501,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Él ... de bloque en bloque sobre el agua verde.'::text,'pasa'::text,'pasar'::text,'pasando'::text,'Él pasa de bloque en bloque sobre el agua verde.'::text),
(319505,35501,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il ... de bloc en bloc au-dessus de l''eau verte.'::text,'passe'::text,'passer'::text,'passant'::text,'Il passe de bloc en bloc au-dessus de l''eau verte.'::text),
(319508,35501,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O yeşil suyun üstünde bloktan bloğa ...'::text,'geçer'::text,'geçmek'::text,'geçerek'::text,'O yeşil suyun üstünde bloktan bloğa geçer.'::text),
(319509,35501,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ő blokkról blokkra ... a zöld víz fölött.'::text,'lép'::text,'lépni'::text,'lépő'::text,'Ő blokkról blokkra lép a zöld víz fölött.'::text),
(319566,35508,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ein echter Profi: Er steigt hinüber, ... er ruft um Hilfe.'::text,'aber'::text,'weil'::text,'also'::text,'Ein echter Profi: Er steigt hinüber, aber er ruft um Hilfe.'::text),
(319570,35508,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Справжній профі: він переходить, ... кличе на допомогу.'::text,'але'::text,'бо'::text,'тому'::text,'Справжній профі: він переходить, але кличе на допомогу.'::text),
(319569,35508,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Todo un profesional: él cruza, ... pide ayuda a gritos.'::text,'pero'::text,'porque'::text,'así que'::text,'Todo un profesional: él cruza, pero pide ayuda a gritos.'::text),
(319568,35508,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Un vrai pro : il traverse, ... il appelle à l''aide.'::text,'mais'::text,'parce que'::text,'donc'::text,'Un vrai pro : il traverse, mais il appelle à l''aide.'::text),
(319571,35508,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tam bir profesyonel: o karşıya geçiyor ... yardım için bağırıyor.'::text,'ama'::text,'çünkü'::text,'bu yüzden'::text,'Tam bir profesyonel: o karşıya geçiyor ama yardım için bağırıyor.'::text),
(319572,35508,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Igazi profi: ő átlép, ... segítségért kiabál.'::text,'de'::text,'mert'::text,'ezért'::text,'Igazi profi: ő átlép, de segítségért kiabál.'::text),
(317532,35282,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Respekt, du ... ein echtes Talent dafür, ihr Lächeln einzufangen.'::text,'hast'::text,'hat'::text,'hast'::text,'Respekt, du hast ein echtes Talent dafür, ihr Lächeln einzufangen.'::text),
(317536,35282,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Респект, ти ... справжній талант ловити її усмішку.'::text,'маєш'::text,'має'::text,'маєш'::text,'Респект, ти маєш справжній талант ловити її усмішку.'::text),
(317535,35282,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Respeto, tú ... un talento de verdad para captar su sonrisa.'::text,'tienes'::text,'tiene'::text,'tienes'::text,'Respeto, tú tienes un talento de verdad para captar su sonrisa.'::text),
(317534,35282,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Respect, tu ... un vrai talent pour capturer son sourire.'::text,'as'::text,'a'::text,'as'::text,'Respect, tu as un vrai talent pour capturer son sourire.'::text),
(317537,35282,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Saygılar, senin onun gülüşünü yakalamakta gerçek bir yeteneğin ...'::text,'var'::text,'var'::text,'var'::text,'Saygılar, senin onun gülüşünü yakalamakta gerçek bir yeteneğin var.'::text),
(317538,35282,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Respekt, neked ... igazi tehetséged a mosolya elkapásához.'::text,'van'::text,'van'::text,'van'::text,'Respekt, neked van igazi tehetséged a mosolya elkapásához.'::text),
(317586,35288,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bestie, ich hab gehört, er hat so ... Fotos von ihrem Lächeln gemacht.'::text,'viele'::text,'viel'::text,'irgendwelche'::text,'Bestie, ich hab gehört, er hat so viele Fotos von ihrem Lächeln gemacht.'::text),
(317590,35288,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Подруго, я чула, що він зробив так ... фото її усмішки.'::text,'багато'::text,'багато'::text,'якихось'::text,'Подруго, я чула, що він зробив так багато фото її усмішки.'::text),
(317589,35288,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Amiga, me han dicho que él hizo ... fotos de su sonrisa.'::text,'tantas'::text,'tanta'::text,'cualquier'::text,'Amiga, me han dicho que él hizo tantas fotos de su sonrisa.'::text),
(317588,35288,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ma belle, il paraît qu''il a pris ... photos de son sourire.'::text,'tellement de'::text,'tellement de'::text,'n''importe quelles'::text,'Ma belle, il paraît qu''il a pris tellement de photos de son sourire.'::text),
(317591,35288,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, duydum ki o, onun gülüşünün o kadar ... fotoğrafını çekmiş.'::text,'çok'::text,'çok'::text,'herhangi bir'::text,'Kanka, duydum ki o, onun gülüşünün o kadar çok fotoğrafını çekmiş.'::text),
(317592,35288,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Csajszi, azt hallottam, hogy ő olyan ... fotót csinált a mosolyáról.'::text,'sok'::text,'sok'::text,'bármilyen'::text,'Csajszi, azt hallottam, hogy ő olyan sok fotót csinált a mosolyáról.'::text),
(304356,33818,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er liebt sie, aber er ... eine Hand am Lenkrad lassen. Makellos.'::text,'muss'::text,'muss'::text,'sollte'::text,'Er liebt sie, aber er muss eine Hand am Lenkrad lassen. Makellos.'::text),
(304360,33818,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він її кохає, але він ... тримати руку на кермі. Бездоганно.'::text,'має'::text,'мусить'::text,'мав би'::text,'Він її кохає, але він має тримати руку на кермі. Бездоганно.'::text),
(304359,33818,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Él la quiere, pero ... mantener una mano en el volante. Impecable.'::text,'tiene que'::text,'debe'::text,'debería'::text,'Él la quiere, pero tiene que mantener una mano en el volante. Impecable.'::text),
(304358,33818,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il l''aime, mais il ... garder une main sur le volant. Impeccable.'::text,'doit'::text,'doit'::text,'devrait'::text,'Il l''aime, mais il doit garder une main sur le volant. Impeccable.'::text),
(304361,33818,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O onu seviyor ama bir elini direksiyonda ..., kusursuz.'::text,'tutmak zorunda'::text,'tutmalı'::text,'tutmalı'::text,'O onu seviyor ama bir elini direksiyonda tutmak zorunda, kusursuz.'::text),
(304362,33818,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ő szereti a lányt, de az egyik kezét a kormányon ... tartania. Hibátlan.'::text,'kell'::text,'kell'::text,'kellene'::text,'Ő szereti a lányt, de az egyik kezét a kormányon kell tartania. Hibátlan.'::text),
(304806,33868,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie essen ihre Mahlzeit ... Sonnenuntergang am Strand.'::text,'bei'::text,'im'::text,'am'::text,'Sie essen ihre Mahlzeit bei Sonnenuntergang am Strand.'::text),
(304810,33868,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вони їдять свою страву ... заході сонця на пляжі.'::text,'на'::text,'у'::text,'на'::text,'Вони їдять свою страву на заході сонця на пляжі.'::text),
(304809,33868,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ellos toman su comida ... atardecer en la playa.'::text,'al'::text,'en el'::text,'sobre el'::text,'Ellos toman su comida al atardecer en la playa.'::text),
(304808,33868,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ils prennent leur repas ... coucher du soleil sur la plage.'::text,'au'::text,'dans le'::text,'sur le'::text,'Ils prennent leur repas au coucher du soleil sur la plage.'::text),
(304811,33868,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Onlar yemeklerini sahilde ... yiyor.'::text,'gün batımında'::text,'gün batımında'::text,'gün batımında'::text,'Onlar yemeklerini sahilde gün batımında yiyor.'::text),
(304812,33868,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ők ... fogyasztják el az ételüket a strandon.'::text,'naplementekor'::text,'naplementében'::text,'naplementén'::text,'Ők naplementekor fogyasztják el az ételüket a strandon.'::text),
(304851,33873,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Budget: Diese Mahlzeit kostet 60 Euro, also ... wir uns die Pommes teilen.'::text,'sollten'::text,'sollten'::text,'sollten'::text,'Budget: Diese Mahlzeit kostet 60 Euro, also sollten wir uns die Pommes teilen.'::text),
(304855,33873,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бюджет: ця страва коштує 60 євро, тож ми ... поділити картоплю фрі.'::text,'мали б'::text,'мали б'::text,'мали б'::text,'Бюджет: ця страва коштує 60 євро, тож ми мали б поділити картоплю фрі.'::text),
(304854,33873,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Presupuesto: esta comida cuesta 60 euros, así que nosotros ... compartir las patatas fritas.'::text,'deberíamos'::text,'deberíamos'::text,'deberíamos'::text,'Presupuesto: esta comida cuesta 60 euros, así que nosotros deberíamos compartir las patatas fritas.'::text),
(304853,33873,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Budget : ce repas coûte 60 euros, donc nous ... partager les frites.'::text,'devrions'::text,'devrions'::text,'devrions'::text,'Budget : ce repas coûte 60 euros, donc nous devrions partager les frites.'::text),
(304856,33873,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bütçe: bu yemek 60 euro, bu yüzden biz patatesleri ...'::text,'paylaşmalıyız'::text,'paylaşmalıyız'::text,'paylaşmalıyız'::text,'Bütçe: bu yemek 60 euro, bu yüzden biz patatesleri paylaşmalıyız.'::text),
(304857,33873,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Költségvetés: ez az étel 60 euró, ezért nekünk ... megosztanunk a sült krumplit.'::text,'kellene'::text,'kellene'::text,'kellene'::text,'Költségvetés: ez az étel 60 euró, ezért nekünk kellene megosztanunk a sült krumplit.'::text),
(320016,35558,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie trinkt vor dem Laden ... Kokosnuss, also ist es ihre Kokosnuss.'::text,'ihre'::text,'seine'::text,'seine'::text,'Sie trinkt vor dem Laden ihre Kokosnuss, also ist es ihre Kokosnuss.'::text),
(320020,35558,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона п''є ... кокос біля магазину, тож це її кокос.'::text,'свій'::text,'свій'::text,'свій'::text,'Вона п''є свій кокос біля магазину, тож це її кокос.'::text),
(320019,35558,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ella bebe ... coco delante de la tienda, así que es su coco.'::text,'su'::text,'su'::text,'su'::text,'Ella bebe su coco delante de la tienda, así que es su coco.'::text),
(320018,35558,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle boit ... noix de coco devant le magasin, donc c''est sa noix de coco.'::text,'sa'::text,'sa'::text,'sa'::text,'Elle boit sa noix de coco devant le magasin, donc c''est sa noix de coco.'::text),
(320021,35558,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O, mağazanın önünde ... hindistancevizini içiyor, yani bu onun hindistancevizi.'::text,'onun'::text,'onun'::text,'onun'::text,'O, mağazanın önünde onun hindistancevizini içiyor, yani bu onun hindistancevizi.'::text),
(320022,35558,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ő a ... issza a bolt előtt, tehát ez az ő kókusza.'::text,'kókuszát'::text,'kókuszát'::text,'kókuszát'::text,'Ő a kókuszát issza a bolt előtt, tehát ez az ő kókusza.'::text),
(320052,35562,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er sagt jetzt nein, aber morgen ... sie vor dem Laden wieder fragen.'::text,'wird'::text,'fragt'::text,'fragte'::text,'Er sagt jetzt nein, aber morgen wird sie vor dem Laden wieder fragen.'::text),
(320056,35562,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він зараз каже «ні», але завтра вона ... знову біля магазину.'::text,'спитає'::text,'питає'::text,'спитала'::text,'Він зараз каже «ні», але завтра вона спитає знову біля магазину.'::text),
(320055,35562,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Él dice que no ahora, pero mañana ella ... otra vez delante de la tienda.'::text,'preguntará'::text,'pregunta'::text,'preguntó'::text,'Él dice que no ahora, pero mañana ella preguntará otra vez delante de la tienda.'::text),
(320054,35562,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il dit non maintenant, mais demain elle ... encore devant le magasin.'::text,'demandera'::text,'demande'::text,'a demandé'::text,'Il dit non maintenant, mais demain elle demandera encore devant le magasin.'::text),
(320057,35562,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O şimdi hayır diyor ama yarın o mağazanın önünde yine ...'::text,'soracak'::text,'sorar'::text,'sordu'::text,'O şimdi hayır diyor ama yarın o mağazanın önünde yine soracak.'::text),
(320058,35562,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ő most nemet mond, de holnap a lány újra ... a bolt előtt.'::text,'meg fogja kérdezni'::text,'megkérdezi'::text,'megkérdezte'::text,'Ő most nemet mond, de holnap a lány újra meg fogja kérdezni a bolt előtt.'::text),
(310701,34523,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie ... die ganze Nacht Golf trainieren! Der Mann ist total geschockt!'::text,'kann'::text,'kann'::text,'ist'::text,'Sie kann die ganze Nacht Golf trainieren! Der Mann ist total geschockt!'::text),
(310705,34523,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона ... тренувати гольф цілу ніч! Чоловік у повному шоці!'::text,'може'::text,'може'::text,'є'::text,'Вона може тренувати гольф цілу ніч! Чоловік у повному шоці!'::text),
(310704,34523,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Ella ... practicar golf toda la noche! ¡El hombre está en shock total!'::text,'puede'::text,'puede'::text,'está'::text,'¡Ella puede practicar golf toda la noche! ¡El hombre está en shock total!'::text),
(310703,34523,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle ... s''entraîner au golf toute la nuit ! L''homme est complètement choqué !'::text,'peut'::text,'peut'::text,'est'::text,'Elle peut s''entraîner au golf toute la nuit ! L''homme est complètement choqué !'::text),
(310706,34523,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O bütün gece golf ...! Adam tamamen şokta!'::text,'çalışabilir'::text,'çalışabilir'::text,NULL::text,'O bütün gece golf çalışabilir! Adam tamamen şokta!'::text),
(310707,34523,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ő egész éjjel ... golfozni! A férfi teljesen le van döbbenve!'::text,'tud'::text,'tud'::text,'van'::text,'Ő egész éjjel tud golfozni! A férfi teljesen le van döbbenve!'::text),
(310719,34525,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mädel, er hat mir erzählt, sie ... gestern bis Mitternacht hier Golf.'::text,'trainierte'::text,'trainiert'::text,'trainieren'::text,'Mädel, er hat mir erzählt, sie trainierte gestern bis Mitternacht hier Golf.'::text),
(310723,34525,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Подруго, він мені сказав, що вона ... гольф тут до півночі вчора.'::text,'тренувала'::text,'тренує'::text,'тренувати'::text,'Подруго, він мені сказав, що вона тренувала гольф тут до півночі вчора.'::text),
(310722,34525,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tía, él me dijo que ella ... golf aquí hasta medianoche ayer.'::text,'practicó'::text,'practica'::text,'practicar'::text,'Tía, él me dijo que ella practicó golf aquí hasta medianoche ayer.'::text),
(310721,34525,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ma belle, il m''a dit qu''elle ... le golf ici jusqu''à minuit hier.'::text,'a pratiqué'::text,'pratique'::text,'pratiquer'::text,'Ma belle, il m''a dit qu''elle a pratiqué le golf ici jusqu''à minuit hier.'::text),
(310724,34525,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kızım, bana dediğine göre o dün burada gece yarısına kadar golf ...'::text,'çalıştı'::text,'çalışır'::text,'çalışmak'::text,'Kızım, bana dediğine göre o dün burada gece yarısına kadar golf çalıştı.'::text),
(310725,34525,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Csajszi, azt mondta nekem, hogy ő tegnap éjfélig itt ... golfot.'::text,'gyakorolt'::text,'gyakorol'::text,'gyakorolni'::text,'Csajszi, azt mondta nekem, hogy ő tegnap éjfélig itt gyakorolt golfot.'::text),
(294519,32725,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... findet er sein Handy? Auf dem Fensterbrett.'::text,'Wo'::text,'Wann'::text,'Wer'::text,'Wo findet er sein Handy? Auf dem Fensterbrett.'::text),
(294523,32725,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... він знаходить свій телефон? На підвіконні.'::text,'Де'::text,'Коли'::text,'Хто'::text,'Де він знаходить свій телефон? На підвіконні.'::text),
(294522,32725,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¿... encuentra él su móvil? En el alféizar.'::text,'Dónde'::text,'Cuándo'::text,'Quién'::text,'¿Dónde encuentra él su móvil? En el alféizar.'::text),
(294521,32725,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... trouve-t-il son téléphone ? Sur le rebord de la fenêtre.'::text,'Où'::text,'Quand'::text,'Qui'::text,'Où trouve-t-il son téléphone ? Sur le rebord de la fenêtre.'::text),
(294524,32725,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O telefonunu ... buluyor? Pencere pervazında.'::text,'nerede'::text,'ne zaman'::text,'kim'::text,'O telefonunu nerede buluyor? Pencere pervazında.'::text),
(294525,32725,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... találja meg ő a telefonját? Az ablakpárkányon.'::text,'Hol'::text,'Mikor'::text,'Ki'::text,'Hol találja meg ő a telefonját? Az ablakpárkányon.'::text),
(294564,32730,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er hat das Handy endlich gefunden, ... die Frau hat nicht geholfen! Das Schlimmste!'::text,'aber'::text,'also'::text,'weil'::text,'Er hat das Handy endlich gefunden, aber die Frau hat nicht geholfen! Das Schlimmste!'::text),
(294568,32730,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він нарешті знайшов телефон, ... жінка не допомогла! Жах!'::text,'але'::text,'тому'::text,'бо'::text,'Він нарешті знайшов телефон, але жінка не допомогла! Жах!'::text),
(294567,32730,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Él por fin encontró el móvil, ... la mujer no ayudó! ¡Lo peor!'::text,'pero'::text,'así que'::text,'porque'::text,'¡Él por fin encontró el móvil, pero la mujer no ayudó! ¡Lo peor!'::text),
(294566,32730,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il a enfin trouvé le téléphone, ... la femme n''a pas aidé ! Le pire !'::text,'mais'::text,'donc'::text,'parce que'::text,'Il a enfin trouvé le téléphone, mais la femme n''a pas aidé ! Le pire !'::text),
(294569,32730,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O sonunda telefonu buldu ... kadın yardım etmedi! Berbat!'::text,'ama'::text,'bu yüzden'::text,'çünkü'::text,'O sonunda telefonu buldu ama kadın yardım etmedi! Berbat!'::text),
(294570,32730,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ő végre megtalálta a telefont, ... a nő nem segített! A legrosszabb!'::text,'de'::text,'ezért'::text,'mert'::text,'Ő végre megtalálta a telefont, de a nő nem segített! A legrosszabb!'::text),
(300234,33360,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nein! Morgen verlieren sie ... Urlaub für immer!'::text,'ihren'::text,'seinen'::text,'seinen'::text,'Nein! Morgen verlieren sie ihren Urlaub für immer!'::text),
(300238,33360,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ні! Завтра вони назавжди втратять ... відпустку!'::text,'свою'::text,'свою'::text,'свою'::text,'Ні! Завтра вони назавжди втратять свою відпустку!'::text),
(300237,33360,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡No! ¡Mañana ellos pierden ... vacaciones para siempre!'::text,'sus'::text,'sus'::text,'sus'::text,'¡No! ¡Mañana ellos pierden sus vacaciones para siempre!'::text),
(300236,33360,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Non ! Demain, ils perdent ... vacances pour toujours !'::text,'leurs'::text,'ses'::text,'ses'::text,'Non ! Demain, ils perdent leurs vacances pour toujours !'::text),
(300239,33360,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hayır! Yarın onlar ... tatillerini sonsuza dek kaybediyor!'::text,'onların'::text,'onun'::text,'onun'::text,'Hayır! Yarın onlar onların tatillerini sonsuza dek kaybediyor!'::text),
(300240,33360,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ne! Holnap ők örökre elveszítik a ...!'::text,'szabadságukat'::text,'szabadságát'::text,'szabadságát'::text,'Ne! Holnap ők örökre elveszítik a szabadságukat!'::text),
(300270,33364,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hör zu, anscheinend hat er in diesem Urlaub so ... Fotos gemacht.'::text,'viele'::text,'viel'::text,'irgendwelche'::text,'Hör zu, anscheinend hat er in diesem Urlaub so viele Fotos gemacht.'::text),
(300274,33364,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Слухай, він, кажуть, зробив так ... фото у цій відпустці.'::text,'багато'::text,'багато'::text,'якихось'::text,'Слухай, він, кажуть, зробив так багато фото у цій відпустці.'::text),
(300273,33364,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Oye, parece que él hizo ... fotos en estas vacaciones.'::text,'tantas'::text,'tanta'::text,'cualquier'::text,'Oye, parece que él hizo tantas fotos en estas vacaciones.'::text),
(300272,33364,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Écoute, apparemment il a pris ... photos pendant ces vacances.'::text,'tellement de'::text,'tellement de'::text,'n''importe quelles'::text,'Écoute, apparemment il a pris tellement de photos pendant ces vacances.'::text),
(300275,33364,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dinle, görünüşe göre o bu tatilde o kadar ... fotoğraf çekmiş.'::text,'çok'::text,'çok'::text,'herhangi bir'::text,'Dinle, görünüşe göre o bu tatilde o kadar çok fotoğraf çekmiş.'::text),
(300276,33364,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Figyelj, állítólag ő olyan ... fotót csinált ezen a nyaraláson.'::text,'sok'::text,'sok'::text,'bármilyen'::text,'Figyelj, állítólag ő olyan sok fotót csinált ezen a nyaraláson.'::text),
(304086,33788,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Last erdrückt ... Schultern! Totale Katastrophe!'::text,'seine'::text,'ihre'::text,'seine'::text,'Die Last erdrückt seine Schultern! Totale Katastrophe!'::text),
(304090,33788,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вантаж розчавлює ... плечі! Повна катастрофа!'::text,'його'::text,'її'::text,'його'::text,'Вантаж розчавлює його плечі! Повна катастрофа!'::text),
(304089,33788,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡La carga le está aplastando ... hombros! ¡Desastre total!'::text,'sus'::text,'sus'::text,'sus'::text,'¡La carga le está aplastando sus hombros! ¡Desastre total!'::text),
(304088,33788,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La charge est en train d''écraser ... épaules ! Désastre total !'::text,'ses'::text,'ses'::text,'ses'::text,'La charge est en train d''écraser ses épaules ! Désastre total !'::text),
(304091,33788,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yük ... omuzlarını eziyor! Tam bir felaket!'::text,'onun'::text,'onun'::text,'onun'::text,'Yük onun omuzlarını eziyor! Tam bir felaket!'::text),
(304092,33788,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A teher összenyomja a ...! Teljes katasztrófa!'::text,'vállát'::text,'vállát'::text,'vállát'::text,'A teher összenyomja a vállát! Teljes katasztrófa!'::text),
(304113,33791,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'In seiner Ladung ... zwanzig Liegen.'::text,'sind'::text,'ist'::text,'sein'::text,'In seiner Ladung sind zwanzig Liegen.'::text),
(304117,33791,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'У його вантажі ... двадцять лежаків.'::text,'є'::text,'є'::text,'бути'::text,'У його вантажі є двадцять лежаків.'::text),
(304116,33791,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... veinte tumbonas en su carga.'::text,'Hay'::text,'Hay'::text,'Hay'::text,'Hay veinte tumbonas en su carga.'::text),
(304115,33791,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... vingt transats dans son chargement.'::text,'Il y a'::text,'Il y a'::text,'Il y a'::text,'Il y a vingt transats dans son chargement.'::text),
(304118,33791,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Onun yükünde yirmi şezlong ...'::text,'var'::text,'var'::text,'olmak'::text,'Onun yükünde yirmi şezlong var.'::text),
(304119,33791,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A rakományában húsz nyugágy ...'::text,'van'::text,'van'::text,'lenni'::text,'A rakományában húsz nyugágy van.'::text),
(295716,32858,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Toller Plan, klar: Vier Freunde ... in einem kleinen Van wohnen.'::text,'werden'::text,'wird'::text,'werden'::text,'Toller Plan, klar: Vier Freunde werden in einem kleinen Van wohnen.'::text),
(295720,32858,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чудовий план, ясно: четверо друзів ... в одному маленькому фургоні.'::text,'збираються жити'::text,'збирається жити'::text,'збираються жити'::text,'Чудовий план, ясно: четверо друзів збираються жити в одному маленькому фургоні.'::text),
(295719,32858,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Gran plan, está claro: cuatro amigos ... en una furgoneta pequeña.'::text,'van a vivir'::text,'va a vivir'::text,'van a vivir'::text,'Gran plan, está claro: cuatro amigos van a vivir en una furgoneta pequeña.'::text),
(295718,32858,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Super plan, clairement : quatre amis ... dans un seul petit van.'::text,'vont vivre'::text,'va vivre'::text,'vont vivre'::text,'Super plan, clairement : quatre amis vont vivre dans un seul petit van.'::text),
(295721,32858,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Harika plan, belli: dört arkadaş tek bir küçük minibüste ...'::text,'yaşayacak'::text,'yaşayacak'::text,'yaşayacak'::text,'Harika plan, belli: dört arkadaş tek bir küçük minibüste yaşayacak.'::text),
(295722,32858,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Remek terv, egyértelmű: négy barát egyetlen kis furgonban ... lakni.'::text,'fog'::text,'fog'::text,'fog'::text,'Remek terv, egyértelmű: négy barát egyetlen kis furgonban fog lakni.'::text),
(311988,34666,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Das kleine Stativ hält das Handy, also ... es sie aufnehmen.'::text,'kann'::text,'kann'::text,'ist'::text,'Das kleine Stativ hält das Handy, also kann es sie aufnehmen.'::text),
(311992,34666,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Маленький штатив тримає телефон, тож він ... їх знімати.'::text,'може'::text,'може'::text,'є'::text,'Маленький штатив тримає телефон, тож він може їх знімати.'::text),
(311991,34666,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El pequeño trípode sujeta el móvil, así que él ... grabarlos.'::text,'puede'::text,'puede'::text,'está'::text,'El pequeño trípode sujeta el móvil, así que él puede grabarlos.'::text),
