(302272,33586,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона цілує ... щоку, бо його щока там.'::text,'його'::text,'її'::text,'їхню'::text,'Вона цілує його щоку, бо його щока там.'::text),
(302271,33586,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ella le da un beso en ... mejilla porque su mejilla está ahí.'::text,'su'::text,'su'::text,'su'::text,'Ella le da un beso en su mejilla porque su mejilla está ahí.'::text),
(302270,33586,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle pose un bisou sur ... joue parce que sa joue est là.'::text,'sa'::text,'sa'::text,'leur'::text,'Elle pose un bisou sur sa joue parce que sa joue est là.'::text),
(302273,33586,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O ... yanağına bir öpücük konduruyor çünkü onun yanağı orada.'::text,'onun'::text,'onun'::text,'onların'::text,'O onun yanağına bir öpücük konduruyor çünkü onun yanağı orada.'::text),
(302274,33586,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ő puszit nyom a ..., mert az ő arca ott van.'::text,'arcára'::text,'arcára'::text,'arcukra'::text,'Ő puszit nyom a arcára, mert az ő arca ott van.'::text),
(302277,33587,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mädel, sie hat ihm einen Kuss gegeben, ... er hat angeblich weiter finster geguckt.'::text,'aber'::text,'also'::text,'weil'::text,'Mädel, sie hat ihm einen Kuss gegeben, aber er hat angeblich weiter finster geguckt.'::text),
(302281,33587,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Подруго, вона його поцілувала, ... він, кажуть, і далі хмурився.'::text,'але'::text,'тому'::text,'бо'::text,'Подруго, вона його поцілувала, але він, кажуть, і далі хмурився.'::text),
(302280,33587,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tía, ella le dio un beso, ... él siguió frunciendo el ceño, por lo visto.'::text,'pero'::text,'así que'::text,'porque'::text,'Tía, ella le dio un beso, pero él siguió frunciendo el ceño, por lo visto.'::text),
(302279,33587,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ma belle, elle lui a fait un bisou, ... il a continué à faire la tête, apparemment.'::text,'mais'::text,'donc'::text,'parce que'::text,'Ma belle, elle lui a fait un bisou, mais il a continué à faire la tête, apparemment.'::text),
(302282,33587,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kızım, o ona bir öpücük verdi ... o kaşlarını çatmaya devam etti galiba.'::text,'ama'::text,'bu yüzden'::text,'çünkü'::text,'Kızım, o ona bir öpücük verdi ama o kaşlarını çatmaya devam etti galiba.'::text),
(302283,33587,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Csajszi, ő adott neki egy puszit, ... a srác állítólag tovább mogorván nézett.'::text,'de'::text,'ezért'::text,'mert'::text,'Csajszi, ő adott neki egy puszit, de a srác állítólag tovább mogorván nézett.'::text),
(300630,33404,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der kleine Hund ... sehr hungrig.'::text,'ist'::text,'sind'::text,'bin'::text,'Der kleine Hund ist sehr hungrig.'::text),
(300634,33404,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Маленький песик ... дуже голодний.'::text,'є'::text,'є'::text,'є'::text,'Маленький песик є дуже голодний.'::text),
(300633,33404,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El perrito ... muy hambriento.'::text,'está'::text,'están'::text,'estoy'::text,'El perrito está muy hambriento.'::text),
(300632,33404,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le petit chien ... très affamé.'::text,'est'::text,'sont'::text,'suis'::text,'Le petit chien est très affamé.'::text),
(300635,33404,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Küçük köpek çok aç ...'::text,''::text,NULL::text,NULL::text,'Küçük köpek çok aç.'::text),
(300636,33404,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A kiskutya ... nagyon éhes.'::text,''::text,NULL::text,'vagyok'::text,'A kiskutya nagyon éhes.'::text),
(300693,33411,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der hungrige Hund schnappt sich die Spaghetti ... von der Gabel.'::text,'schnell'::text,'schnell'::text,'Schnelligkeit'::text,'Der hungrige Hund schnappt sich die Spaghetti schnell von der Gabel.'::text),
(300697,33411,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Голодний пес ... хапає спагеті з виделки.'::text,'швидко'::text,'швидкий'::text,'швидкість'::text,'Голодний пес швидко хапає спагеті з виделки.'::text),
(300696,33411,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El perro hambriento coge los espaguetis ... del tenedor.'::text,'rápidamente'::text,'rápido'::text,'rapidez'::text,'El perro hambriento coge los espaguetis rápidamente del tenedor.'::text),
(300695,33411,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le chien affamé prend les spaghettis ... sur la fourchette.'::text,'rapidement'::text,'rapide'::text,'rapidité'::text,'Le chien affamé prend les spaghettis rapidement sur la fourchette.'::text),
(300698,33411,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Aç köpek spagettiyi çataldan ... kapıyor.'::text,'hızlıca'::text,'hızlı'::text,'hızlılık'::text,'Aç köpek spagettiyi çataldan hızlıca kapıyor.'::text),
(300699,33411,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Az éhes kutya ... elkapja a spagettit a villáról.'::text,'gyorsan'::text,'gyors'::text,'gyorsaság'::text,'Az éhes kutya gyorsan elkapja a spagettit a villáról.'::text),
(300963,33441,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Auf der Autotür steht „Ich bin ihr Mann“ in ... Wörtern.'::text,'drei'::text,'dritten'::text,'Dreien'::text,'Auf der Autotür steht „Ich bin ihr Mann“ in drei Wörtern.'::text),
(300967,33441,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'На дверцятах авто написано «Я її чоловік» ... словами.'::text,'трьома'::text,'третіми'::text,'трійками'::text,'На дверцятах авто написано «Я її чоловік» трьома словами.'::text),
(300966,33441,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La puerta del coche dice «Soy su marido» en ... palabras.'::text,'tres'::text,'terceras'::text,'tres'::text,'La puerta del coche dice «Soy su marido» en tres palabras.'::text),
(300965,33441,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La portière dit « Je suis son mari » en ... mots.'::text,'trois'::text,'troisièmes'::text,'trois'::text,'La portière dit « Je suis son mari » en trois mots.'::text),
(300968,33441,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Arabanın kapısında ... kelimeyle “Ben onun kocasıyım” yazıyor.'::text,'üç'::text,'üçüncü'::text,'üçler'::text,'Arabanın kapısında üç kelimeyle “Ben onun kocasıyım” yazıyor.'::text),
(300969,33441,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Az autó ajtaján ... szóban az áll: „A férje vagyok”.'::text,'három'::text,'harmadik'::text,'hármasok'::text,'Az autó ajtaján három szóban az áll: „A férje vagyok”.'::text),
(300990,33444,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ihr Mann lächelt, aber sie sagt: „Ich ... jetzt aussteigen.“'::text,'werde'::text,'werde'::text,NULL::text,'Ihr Mann lächelt, aber sie sagt: „Ich werde jetzt aussteigen.“'::text),
(300994,33444,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Її чоловік усміхається, але вона каже: «Я ... виходити зараз».'::text,'буду'::text,'збираюся'::text,NULL::text,'Її чоловік усміхається, але вона каже: «Я буду виходити зараз».'::text),
(300993,33444,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Su marido sonríe, pero ella dice: «Yo ... ahora».'::text,'me bajaré'::text,'voy a bajarme'::text,NULL::text,'Su marido sonríe, pero ella dice: «Yo me bajaré ahora».'::text),
(300992,33444,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Son mari sourit, mais elle dit : « Je ... maintenant. »'::text,'descendrai'::text,'vais descendre'::text,NULL::text,'Son mari sourit, mais elle dit : « Je descendrai maintenant. »'::text),
(300995,33444,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kocası gülümsüyor ama o “Ben şimdi ...” diyor.'::text,'ineceğim'::text,'ineceğim'::text,NULL::text,'Kocası gülümsüyor ama o “Ben şimdi ineceğim” diyor.'::text),
(300996,33444,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A férje mosolyog, de ő azt mondja: „Én most ki ... szállni.”'::text,'fogok'::text,'fogok'::text,NULL::text,'A férje mosolyog, de ő azt mondja: „Én most ki fogok szállni.”'::text),
(301512,33502,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die graue Taube ... etwas rosa Schmuck.'::text,'hat'::text,'haben'::text,'hat'::text,'Die graue Taube hat etwas rosa Schmuck.'::text),
(301516,33502,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Сірий голуб ... рожеві прикраси.'::text,'має'::text,'мати'::text,'має'::text,'Сірий голуб має рожеві прикраси.'::text),
(301515,33502,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La paloma gris ... algunas joyas rosas.'::text,'tiene'::text,'tienen'::text,'tiene'::text,'La paloma gris tiene algunas joyas rosas.'::text),
(301514,33502,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le pigeon gris ... des bijoux roses.'::text,'a'::text,'ont'::text,'a'::text,'Le pigeon gris a des bijoux roses.'::text),
(301517,33502,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Gri güvercinin biraz pembe mücevheri ...'::text,'var'::text,'var'::text,'var'::text,'Gri güvercinin biraz pembe mücevheri var.'::text),
(301518,33502,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A szürke galambnak ... néhány rózsaszín ékszere.'::text,'van'::text,'van'::text,'van'::text,'A szürke galambnak van néhány rózsaszín ékszere.'::text),
(301575,33509,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die weiße Taube mag den Schmuck, ... beugt sie sich nah heran.'::text,'also'::text,'aber'::text,'weil'::text,'Die weiße Taube mag den Schmuck, also beugt sie sich nah heran.'::text),
(301579,33509,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Білій голубці подобаються прикраси, ... вона нахиляється ближче.'::text,'тому'::text,'але'::text,'бо'::text,'Білій голубці подобаються прикраси, тому вона нахиляється ближче.'::text),
(301578,33509,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A la paloma blanca le gustan las joyas, ... ella se acerca mucho.'::text,'así que'::text,'pero'::text,'porque'::text,'A la paloma blanca le gustan las joyas, así que ella se acerca mucho.'::text),
(301577,33509,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La colombe blanche aime les bijoux, ... elle se penche tout près.'::text,'donc'::text,'mais'::text,'parce que'::text,'La colombe blanche aime les bijoux, donc elle se penche tout près.'::text),
(301580,33509,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Beyaz güvercin mücevheri beğeniyor ... o iyice yaklaşıyor.'::text,'bu yüzden'::text,'ama'::text,'çünkü'::text,'Beyaz güvercin mücevheri beğeniyor bu yüzden o iyice yaklaşıyor.'::text),
(301581,33509,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A fehér galambnak tetszik az ékszer, ... ő közel hajol.'::text,'ezért'::text,'de'::text,'mert'::text,'A fehér galambnak tetszik az ékszer, ezért ő közel hajol.'::text),
(323760,35974,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Frau im weißen Rock ist ... Touristin.'::text,'eine'::text,'die'::text,'eine'::text,'Die Frau im weißen Rock ist eine Touristin.'::text),
(323764,35974,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Жінка в білій спідниці — ... туристка.'::text,''::text,NULL::text,NULL::text,'Жінка в білій спідниці — туристка.'::text),
(323763,35974,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La mujer de la falda blanca es ... turista.'::text,'una'::text,'la'::text,'una'::text,'La mujer de la falda blanca es una turista.'::text),
(323762,35974,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La femme à la jupe blanche est ... touriste.'::text,'une'::text,'la'::text,'une'::text,'La femme à la jupe blanche est une touriste.'::text),
(323765,35974,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Beyaz etekli kadın ... turist.'::text,'bir'::text,NULL::text,'bir'::text,'Beyaz etekli kadın bir turist.'::text),
(323766,35974,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A fehér szoknyás nő ... turista.'::text,'egy'::text,'a'::text,'egy'::text,'A fehér szoknyás nő egy turista.'::text),
(323787,35977,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Da ... Hüte für Touristen, weil Touristen Köpfe haben.'::text,'sind'::text,'ist'::text,'sein'::text,'Da sind Hüte für Touristen, weil Touristen Köpfe haben.'::text),
(323791,35977,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... капелюхи для туристів, бо в туристів є голови.'::text,'Є'::text,'Є'::text,'Бути'::text,'Є капелюхи для туристів, бо в туристів є голови.'::text),
(323790,35977,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... sombreros para turistas, porque los turistas tienen cabeza.'::text,'Hay'::text,'Hay'::text,'Hay'::text,'Hay sombreros para turistas, porque los turistas tienen cabeza.'::text),
(323789,35977,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... des chapeaux pour les touristes, parce que les touristes ont une tête.'::text,'Il y a'::text,'Il y a'::text,'Il y a'::text,'Il y a des chapeaux pour les touristes, parce que les touristes ont une tête.'::text),
(323792,35977,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Turistler için şapkalar ... çünkü turistlerin kafaları var.'::text,'var'::text,'var'::text,'olmak'::text,'Turistler için şapkalar var çünkü turistlerin kafaları var.'::text),
(323793,35977,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... kalapok a turistáknak, mert a turistáknak van fejük.'::text,'Vannak'::text,'Van'::text,'Lenni'::text,'Vannak kalapok a turistáknak, mert a turistáknak van fejük.'::text),
(317379,35265,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... parkt er das kleine rote Auto? Unter einem großen Baum.'::text,'Wo'::text,'Wann'::text,'Wer'::text,'Wo parkt er das kleine rote Auto? Unter einem großen Baum.'::text),
(317383,35265,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... він паркує маленьку червону машину? Під великим деревом.'::text,'Де'::text,'Коли'::text,'Хто'::text,'Де він паркує маленьку червону машину? Під великим деревом.'::text),
(317382,35265,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¿... aparca él el pequeño coche rojo? Bajo un árbol grande.'::text,'Dónde'::text,'Cuándo'::text,'Quién'::text,'¿Dónde aparca él el pequeño coche rojo? Bajo un árbol grande.'::text),
(317381,35265,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... gare-t-il la petite voiture rouge ? Sous un grand arbre.'::text,'Où'::text,'Quand'::text,'Qui'::text,'Où gare-t-il la petite voiture rouge ? Sous un grand arbre.'::text),
(317384,35265,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O, küçük kırmızı arabayı ... park ediyor? Büyük bir ağacın altına.'::text,'nereye'::text,'ne zaman'::text,'kim'::text,'O, küçük kırmızı arabayı nereye park ediyor? Büyük bir ağacın altına.'::text),
(317385,35265,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... parkolja le ő a kis piros autót? Egy nagy fa alatt.'::text,'Hol'::text,'Mikor'::text,'Ki'::text,'Hol parkolja le ő a kis piros autót? Egy nagy fa alatt.'::text),
(317388,35266,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er ... gestern in das kleine Auto. Eine echte Limousine, klar.'::text,'kletterte'::text,'klettert'::text,'klettern'::text,'Er kletterte gestern in das kleine Auto. Eine echte Limousine, klar.'::text),
(317392,35266,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він учора ... в маленьку машину. Справжній лімузин, очевидно.'::text,'заліз'::text,'залазить'::text,'залазити'::text,'Він учора заліз в маленьку машину. Справжній лімузин, очевидно.'::text),
(317391,35266,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Él ... al pequeño coche ayer. Una auténtica limusina, claro.'::text,'se subió'::text,'se sube'::text,'subirse'::text,'Él se subió al pequeño coche ayer. Una auténtica limusina, claro.'::text),
(317390,35266,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il ... dans la petite voiture hier. Une vraie limousine, évidemment.'::text,'a grimpé'::text,'grimpe'::text,'grimper'::text,'Il a grimpé dans la petite voiture hier. Une vraie limousine, évidemment.'::text),
(317393,35266,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O dün küçük arabaya ...; gerçek bir limuzin, belli ki.'::text,'tırmandı'::text,'tırmanır'::text,'tırmanmak'::text,'O dün küçük arabaya tırmandı; gerçek bir limuzin, belli ki.'::text),
(317394,35266,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ő tegnap ... a kis autóba. Igazi limuzin, nyilván.'::text,'bemászott'::text,'bemászik'::text,'bemászni'::text,'Ő tegnap bemászott a kis autóba. Igazi limuzin, nyilván.'::text),
(314625,34959,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er sucht ... Wohnzimmer.'::text,'im'::text,'auf dem'::text,'am'::text,'Er sucht im Wohnzimmer.'::text),
(314629,34959,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він шукає ... вітальні.'::text,'у'::text,'на'::text,'біля'::text,'Він шукає у вітальні.'::text),
(314628,34959,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Él hace una búsqueda ... el salón.'::text,'en'::text,'sobre'::text,'a'::text,'Él hace una búsqueda en el salón.'::text),
(314627,34959,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il fait une fouille ... le salon.'::text,'dans'::text,'sur'::text,'à'::text,'Il fait une fouille dans le salon.'::text),
(314630,34959,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O ... arama yapıyor.'::text,'oturma odasında'::text,'oturma odasının üstünde'::text,'oturma odasının yanında'::text,'O oturma odasında arama yapıyor.'::text),
(314631,34959,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ő ... keresgél.'::text,'a nappaliban'::text,'a nappalin'::text,'a nappalinál'::text,'Ő a nappaliban keresgél.'::text),
(314661,34963,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie zeigt auf die Schlüssel, also ... die Suche in einer Sekunde enden.'::text,'wird'::text,'wird'::text,NULL::text,'Sie zeigt auf die Schlüssel, also wird die Suche in einer Sekunde enden.'::text),
(314665,34963,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона показує на ключі, тож пошуки ... за секунду.'::text,'збираються закінчитися'::text,'закінчаться'::text,NULL::text,'Вона показує на ключі, тож пошуки збираються закінчитися за секунду.'::text),
