(293992,32666,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бюджет на стрижку: 20 євро. ... платить — товстий їжак чи кіт?'::text,'Хто'::text,'Що'::text,'Де'::text,'Бюджет на стрижку: 20 євро. Хто платить — товстий їжак чи кіт?'::text),
