(293990,32666,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Budget coupe : 20 euros. ... paie, le gros hérisson ou le chat ?'::text,'Qui'::text,'Que'::text,'Où'::text,'Budget coupe : 20 euros. Qui paie, le gros hérisson ou le chat ?'::text),
(293993,32666,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Saç kesimi bütçesi: 20 euro. ... ödüyor, şişman kirpi mi, kedi mi?'::text,'Kim'::text,'Ne'::text,'Nerede'::text,'Saç kesimi bütçesi: 20 euro. Kim ödüyor, şişman kirpi mi, kedi mi?'::text),
(293994,32666,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hajvágási keret: 20 euró. ... fizet, a kövér sündisznó vagy a macska?'::text,'Ki'::text,'Mi'::text,'Hol'::text,'Hajvágási keret: 20 euró. Ki fizet, a kövér sündisznó vagy a macska?'::text),
(294042,32672,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bruh, die Katze hat den dicken Igel so ... rasiert, jetzt ist er erledigt.'::text,'sorgfältig'::text,'sorgfältig'::text,'Sorgfalt'::text,'Bruh, die Katze hat den dicken Igel so sorgfältig rasiert, jetzt ist er erledigt.'::text),
(294046,32672,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бро, кіт так ... поголив товстого їжака, тепер йому капець.'::text,'ретельно'::text,'ретельний'::text,'ретельність'::text,'Бро, кіт так ретельно поголив товстого їжака, тепер йому капець.'::text),
(294045,32672,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tío, el gato afeitó al erizo gordo tan ..., ahora está acabado.'::text,'cuidadosamente'::text,'cuidadoso'::text,'cuidado'::text,'Tío, el gato afeitó al erizo gordo tan cuidadosamente, ahora está acabado.'::text),
(294044,32672,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Frérot, le chat a rasé le gros hérisson si ..., maintenant il est cuit.'::text,'soigneusement'::text,'soigneux'::text,'soin'::text,'Frérot, le chat a rasé le gros hérisson si soigneusement, maintenant il est cuit.'::text),
(294047,32672,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, kedi şişman kirpiyi o kadar ... tıraş etti ki, artık yandı.'::text,'dikkatlice'::text,'dikkatli'::text,'dikkat'::text,'Kanka, kedi şişman kirpiyi o kadar dikkatlice tıraş etti ki, artık yandı.'::text),
(294048,32672,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, a macska olyan ... borotválta le a kövér sünit, hogy most már neki annyi.'::text,'gondosan'::text,'gondos'::text,'gondosság'::text,'Tesó, a macska olyan gondosan borotválta le a kövér sünit, hogy most már neki annyi.'::text),
(328548,36506,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Alter, einen Typen ... Gelb auf einem pinken Teppich muss man einfach lieben.'::text,'in'::text,'auf'::text,'an'::text,'Alter, einen Typen in Gelb auf einem pinken Teppich muss man einfach lieben.'::text),
(328552,36506,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бро, хлопця ... жовтому на рожевому килимі треба просто любити.'::text,'у'::text,'на'::text,'біля'::text,'Бро, хлопця у жовтому на рожевому килимі треба просто любити.'::text),
(328551,36506,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tío, hay que amar a un tipo ... amarillo sobre una alfombra rosa.'::text,'de'::text,'sobre'::text,'a'::text,'Tío, hay que amar a un tipo de amarillo sobre una alfombra rosa.'::text),
(328550,36506,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Frérot, faut adorer un mec ... jaune sur un tapis rose.'::text,'en'::text,'sur'::text,'à'::text,'Frérot, faut adorer un mec en jaune sur un tapis rose.'::text),
(328553,36506,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, pembe halının üstünde sarılar ... bir herifi sevmemek elde değil.'::text,'içinde'::text,'üstünde'::text,NULL::text,'Kanka, pembe halının üstünde sarılar içinde bir herifi sevmemek elde değil.'::text),
(328554,36506,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, imádni kell egy csávót ... egy rózsaszín szőnyegen.'::text,'sárgában'::text,'sárgán'::text,'sárgánál'::text,'Tesó, imádni kell egy csávót sárgában egy rózsaszín szőnyegen.'::text),
(328566,36508,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Gestern ... er ein Kleid in knalligem Gelb für den Hund.'::text,'kaufte'::text,'kauft'::text,'kaufte'::text,'Gestern kaufte er ein Kleid in knalligem Gelb für den Hund.'::text),
(328570,36508,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Учора він ... сукню яскраво-жовтого кольору для собаки.'::text,'купив'::text,'купує'::text,'купив'::text,'Учора він купив сукню яскраво-жовтого кольору для собаки.'::text),
(328569,36508,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ayer él ... un vestido amarillo chillón para el perro.'::text,'compró'::text,'compra'::text,'compró'::text,'Ayer él compró un vestido amarillo chillón para el perro.'::text),
(328568,36508,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hier, il ... une robe jaune vif pour le chien.'::text,'a acheté'::text,'achète'::text,'a acheté'::text,'Hier, il a acheté une robe jaune vif pour le chien.'::text),
(328571,36508,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dün o köpek için parlak sarı bir elbise ...'::text,'aldı'::text,'alır'::text,'aldı'::text,'Dün o köpek için parlak sarı bir elbise aldı.'::text),
(328572,36508,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tegnap ő ... egy élénksárga estélyit a kutyának.'::text,'vett'::text,'vesz'::text,'vett'::text,'Tegnap ő vett egy élénksárga estélyit a kutyának.'::text),
(309000,34334,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er ... dem Hund mit beiden Händen die Ohren.'::text,'streichelt'::text,'streicheln'::text,'streichelnd'::text,'Er streichelt dem Hund mit beiden Händen die Ohren.'::text),
(309004,34334,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він ... собаці вуха обома руками.'::text,'гладить'::text,'гладити'::text,'гладячи'::text,'Він гладить собаці вуха обома руками.'::text),
(309003,34334,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Él le ... las orejas al perro con las dos manos.'::text,'acaricia'::text,'acariciar'::text,'acariciando'::text,'Él le acaricia las orejas al perro con las dos manos.'::text),
(309002,34334,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il ... les oreilles du chien des deux mains.'::text,'caresse'::text,'caresser'::text,'caressant'::text,'Il caresse les oreilles du chien des deux mains.'::text),
(309005,34334,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O köpeğin kulaklarını iki eliyle ...'::text,'okşar'::text,'okşamak'::text,'okşayarak'::text,'O köpeğin kulaklarını iki eliyle okşar.'::text),
(309006,34334,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ő két kézzel ... a kutya fülét.'::text,'simogatja'::text,'simogatni'::text,'simogató'::text,'Ő két kézzel simogatja a kutya fülét.'::text),
(309027,34337,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Alter, der Plan? Er ... den alten Hund den ganzen Tag streicheln, echt.'::text,'wird'::text,'werden'::text,'wird'::text,'Alter, der Plan? Er wird den alten Hund den ganzen Tag streicheln, echt.'::text),
(309031,34337,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бро, план? Він ... гладити того старого пса цілий день, серйозно.'::text,'збирається'::text,'збираються'::text,'збирається'::text,'Бро, план? Він збирається гладити того старого пса цілий день, серйозно.'::text),
(309030,34337,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tío, ¿el plan? Él ... acariciar a ese perro viejo todo el día, en serio.'::text,'va a'::text,'van a'::text,'va a'::text,'Tío, ¿el plan? Él va a acariciar a ese perro viejo todo el día, en serio.'::text),
(309029,34337,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Frérot, le plan ? Il ... caresser ce vieux chien toute la journée, sérieux.'::text,'va'::text,'vont'::text,'va'::text,'Frérot, le plan ? Il va caresser ce vieux chien toute la journée, sérieux.'::text),
(309032,34337,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, plan mı? O bütün gün o yaşlı köpeği ..., cidden.'::text,'okşayacak'::text,'okşayacaklar'::text,'okşayacak'::text,'Kanka, plan mı? O bütün gün o yaşlı köpeği okşayacak, cidden.'::text),
(309033,34337,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, a terv? Ő egész nap ... simogatni azt az öreg kutyát, komolyan.'::text,'fogja'::text,'fogják'::text,'fogja'::text,'Tesó, a terv? Ő egész nap fogja simogatni azt az öreg kutyát, komolyan.'::text),
(311502,34612,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ich glaube, es ... morgen auf der Bergstraße regnen.'::text,'wird'::text,'regnet'::text,'regnete'::text,'Ich glaube, es wird morgen auf der Bergstraße regnen.'::text),
(311506,34612,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Я думаю, завтра на гірській дорозі ... дощ.'::text,'піде'::text,'іде'::text,'йшов'::text,'Я думаю, завтра на гірській дорозі піде дощ.'::text),
(311505,34612,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yo creo que mañana ... en la carretera de montaña.'::text,'lloverá'::text,'llueve'::text,'llovió'::text,'Yo creo que mañana lloverá en la carretera de montaña.'::text),
(311504,34612,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Je pense qu''il ... demain sur la route de montagne.'::text,'pleuvra'::text,'pleut'::text,'a plu'::text,'Je pense qu''il pleuvra demain sur la route de montagne.'::text),
(311507,34612,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ben yarın dağ yolunda yağmur ... diye düşünüyorum.'::text,'yağacak'::text,'yağar'::text,'yağdı'::text,'Ben yarın dağ yolunda yağmur yağacak diye düşünüyorum.'::text),
(311508,34612,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Én úgy gondolom, holnap ... a hegyi úton.'::text,'esni fog'::text,'esik'::text,'esett'::text,'Én úgy gondolom, holnap esni fog a hegyi úton.'::text),
(324984,36110,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Drei ... rennen durch ein graues Rohr.'::text,'Frettchen'::text,'Frettchen'::text,'Frettchen'::text,'Drei Frettchen rennen durch ein graues Rohr.'::text),
(324988,36110,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Три ... біжать крізь одну сіру трубу.'::text,'тхори'::text,'тхір'::text,'тхори'::text,'Три тхори біжать крізь одну сіру трубу.'::text),
(324987,36110,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tres ... corren por un tubo gris.'::text,'hurones'::text,'hurón'::text,'hurones'::text,'Tres hurones corren por un tubo gris.'::text),
(324986,36110,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Trois ... courent dans un tube gris.'::text,'furets'::text,'furet'::text,'furets'::text,'Trois furets courent dans un tube gris.'::text),
(324989,36110,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Üç ... tek bir gri tüpten geçiyor.'::text,'gelincik'::text,'gelincik'::text,'gelincikler'::text,'Üç gelincik tek bir gri tüpten geçiyor.'::text),
(324990,36110,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Három ... fut át egyetlen szürke csövön.'::text,'görény'::text,'görény'::text,'görény'::text,'Három görény fut át egyetlen szürke csövön.'::text),
(324993,36111,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Weißt du was? Die Frettchen machen in dem Rohr so viel ..., hat er gesagt.'::text,'Lärm'::text,'Lärm'::text,'einen Lärm'::text,'Weißt du was? Die Frettchen machen in dem Rohr so viel Lärm, hat er gesagt.'::text),
(324997,36111,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Знаєш що? Тхори здіймають у тій трубі стільки ..., він казав.'::text,'шуму'::text,'шумів'::text,'шуму'::text,'Знаєш що? Тхори здіймають у тій трубі стільки шуму, він казав.'::text),
(324996,36111,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¿Sabes qué? Los hurones hacen tanto ... en ese tubo, dijo él.'::text,'ruido'::text,'ruido'::text,'un ruido'::text,'¿Sabes qué? Los hurones hacen tanto ruido en ese tubo, dijo él.'::text),
(324995,36111,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Devine quoi ? Les furets font tellement de ... dans ce tube, il a dit.'::text,'bruit'::text,'bruit'::text,'un bruit'::text,'Devine quoi ? Les furets font tellement de bruit dans ce tube, il a dit.'::text),
(324998,36111,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bil bakalım ne oldu? Gelincikler o tüpte o kadar çok ... yapıyor, dedi.'::text,'gürültü'::text,'gürültüler'::text,'bir gürültü'::text,'Bil bakalım ne oldu? Gelincikler o tüpte o kadar çok gürültü yapıyor, dedi.'::text),
(324999,36111,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tudod mit? A görények olyan nagy ... csapnak abban a csőben, mondta.'::text,'zajt'::text,'zajt'::text,'egy zajt'::text,'Tudod mit? A görények olyan nagy zajt csapnak abban a csőben, mondta.'::text),
(300711,33413,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... eilt er mit dem Schild? Zum Auto.'::text,'Wohin'::text,'Wer'::text,'Was'::text,'Wohin eilt er mit dem Schild? Zum Auto.'::text),
(300715,33413,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... він поспішає з вивіскою? До машини.'::text,'Куди'::text,'Хто'::text,'Що'::text,'Куди він поспішає з вивіскою? До машини.'::text),
(300714,33413,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¿... va él corriendo con el letrero? Al coche.'::text,'Adónde'::text,'Quién'::text,'Qué'::text,'¿Adónde va él corriendo con el letrero? Al coche.'::text),
(300713,33413,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... se dépêche-t-il avec l''enseigne ? Vers la voiture.'::text,'Où'::text,'Qui'::text,'Que'::text,'Où se dépêche-t-il avec l''enseigne ? Vers la voiture.'::text),
(300716,33413,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O tabelayla ... koşturuyor? Arabaya.'::text,'nereye'::text,'kim'::text,'ne'::text,'O tabelayla nereye koşturuyor? Arabaya.'::text),
(300717,33413,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... siet ő a táblával? Az autóhoz.'::text,'Hová'::text,'Ki'::text,'Mi'::text,'Hová siet ő a táblával? Az autóhoz.'::text),
(300756,33418,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sein Freund ist im Auto, also ... er bald zurückeilen.'::text,'wird'::text,'eilen'::text,'eilte'::text,'Sein Freund ist im Auto, also wird er bald zurückeilen.'::text),
(300760,33418,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Його друг в машині, тож він ... назад незабаром.'::text,'поспішить'::text,'поспішати'::text,'поспішав'::text,'Його друг в машині, тож він поспішить назад незабаром.'::text),
(300759,33418,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Su amigo está en el coche, así que él ... pronto.'::text,'volverá corriendo'::text,'volver corriendo'::text,'volvió corriendo'::text,'Su amigo está en el coche, así que él volverá corriendo pronto.'::text),
(300758,33418,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Son ami est dans la voiture, donc il ... bientôt.'::text,'reviendra en vitesse'::text,'revenir en vitesse'::text,'est revenu en vitesse'::text,'Son ami est dans la voiture, donc il reviendra en vitesse bientôt.'::text),
(300761,33418,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Arkadaşı arabada, bu yüzden o yakında aceleyle ...'::text,'dönecek'::text,'dönmek'::text,'döndü'::text,'Arkadaşı arabada, bu yüzden o yakında aceleyle dönecek.'::text),
(300762,33418,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A barátja az autóban van, ezért ő hamarosan ...'::text,'vissza fog sietni'::text,'visszasietni'::text,'visszasietett'::text,'A barátja az autóban van, ezért ő hamarosan vissza fog sietni.'::text),
(299883,33321,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Autobahn ... links eine Metallleitplanke.'::text,'hat'::text,'haben'::text,'hat'::text,'Die Autobahn hat links eine Metallleitplanke.'::text),
(299887,33321,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Автомагістраль ... металеве огородження ліворуч.'::text,'має'::text,'мати'::text,'має'::text,'Автомагістраль має металеве огородження ліворуч.'::text),
(299886,33321,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La autopista ... una barrera metálica a la izquierda.'::text,'tiene'::text,'tienen'::text,'tiene'::text,'La autopista tiene una barrera metálica a la izquierda.'::text),
(299885,33321,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'L''autoroute ... une glissière métallique à gauche.'::text,'a'::text,'ont'::text,'a'::text,'L''autoroute a une glissière métallique à gauche.'::text),
(299888,33321,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Otoyolun solda metal bir bariyeri ...'::text,'var'::text,'var'::text,'var'::text,'Otoyolun solda metal bir bariyeri var.'::text),
(299889,33321,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Az autópályának bal oldalon ... egy fém szalagkorlátja.'::text,'van'::text,'van'::text,'van'::text,'Az autópályának bal oldalon van egy fém szalagkorlátja.'::text),
(299928,33326,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Also hör zu, ich hab gehört, heute war nicht viel ... auf der Autobahn.'::text,'Verkehr'::text,'Verkehr'::text,'Autos'::text,'Also hör zu, ich hab gehört, heute war nicht viel Verkehr auf der Autobahn.'::text),
(299932,33326,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Слухай, я чула, що сьогодні на трасі було небагато ...'::text,'руху'::text,'рухів'::text,'машин'::text,'Слухай, я чула, що сьогодні на трасі було небагато руху.'::text),
(299931,33326,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Oye, yo he oído que hoy no había mucho ... en la autopista.'::text,'tráfico'::text,'tráfico'::text,'coches'::text,'Oye, yo he oído que hoy no había mucho tráfico en la autopista.'::text),
(299930,33326,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Écoute, j''ai entendu dire qu''il n''y avait pas beaucoup de ... sur l''autoroute aujourd''hui.'::text,'circulation'::text,'circulation'::text,'voitures'::text,'Écoute, j''ai entendu dire qu''il n''y avait pas beaucoup de circulation sur l''autoroute aujourd''hui.'::text),
(299933,33326,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dinle, ben duydum ki bugün otoyolda çok ... yokmuş.'::text,'trafik'::text,'trafikler'::text,'araba'::text,'Dinle, ben duydum ki bugün otoyolda çok trafik yokmuş.'::text),
(299934,33326,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Figyelj, én azt hallottam, hogy ma nem volt nagy ... az autópályán.'::text,'forgalom'::text,'forgalom'::text,'autó'::text,'Figyelj, én azt hallottam, hogy ma nem volt nagy forgalom az autópályán.'::text),
(318837,35427,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Katastrophe! Sie macht ... Mitternacht Sport!'::text,'um'::text,'im'::text,'am'::text,'Katastrophe! Sie macht um Mitternacht Sport!'::text),
(318841,35427,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Катастрофа! Вона займається спортом ... півночі!'::text,'о'::text,'в'::text,'на'::text,'Катастрофа! Вона займається спортом о півночі!'::text),
(318840,35427,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Desastre! ¡Ella hace deporte ... medianoche!'::text,'a'::text,'en'::text,'sobre'::text,'¡Desastre! ¡Ella hace deporte a medianoche!'::text),
(318839,35427,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Catastrophe ! Elle fait du sport ... minuit !'::text,'à'::text,'dans'::text,'sur'::text,'Catastrophe ! Elle fait du sport à minuit !'::text),
(318842,35427,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Felaket! O gece yarısı ... spor yapıyor!'::text,''::text,NULL::text,NULL::text,'Felaket! O gece yarısı spor yapıyor!'::text),
(318843,35427,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Katasztrófa! Ő ... sportol!'::text,'éjfélkor'::text,'éjfélben'::text,'éjfélen'::text,'Katasztrófa! Ő éjfélkor sportol!'::text),
(318864,35430,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie ... normalerweise nachts auf diesem Platz Sport.'::text,'macht'::text,'machte'::text,NULL::text,'Sie macht normalerweise nachts auf diesem Platz Sport.'::text),
(318868,35430,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона зазвичай ... спортом уночі на цьому корті.'::text,'займається'::text,'займалася'::text,NULL::text,'Вона зазвичай займається спортом уночі на цьому корті.'::text),
(318867,35430,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ella normalmente ... deporte de noche en esta pista.'::text,'hace'::text,'hizo'::text,NULL::text,'Ella normalmente hace deporte de noche en esta pista.'::text),
(318866,35430,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'D''habitude, elle ... du sport la nuit sur ce court.'::text,'fait'::text,'a fait'::text,NULL::text,'D''habitude, elle fait du sport la nuit sur ce court.'::text),
(318869,35430,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O genelde geceleri bu kortta spor ...'::text,'yapar'::text,'yaptı'::text,NULL::text,'O genelde geceleri bu kortta spor yapar.'::text),
(318870,35430,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ő általában éjjel ... ezen a pályán.'::text,'sportol'::text,'sportolt'::text,NULL::text,'Ő általában éjjel sportol ezen a pályán.'::text),
(299820,33314,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn ich so hoch fliege, ... ich die kleine Straße unten sehen.'::text,'kann'::text,'kann'::text,'bin'::text,'Wenn ich so hoch fliege, kann ich die kleine Straße unten sehen.'::text),
(299824,33314,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Летячи так високо, я ... бачити маленьку дорогу внизу.'::text,'можу'::text,'можу'::text,'є'::text,'Летячи так високо, я можу бачити маленьку дорогу внизу.'::text),
(299823,33314,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Volando tan alto, yo ... ver la carretera pequeña de abajo.'::text,'puedo'::text,'puedo'::text,'estoy'::text,'Volando tan alto, yo puedo ver la carretera pequeña de abajo.'::text),
(299822,33314,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'En volant aussi haut, je ... voir la petite route en bas.'::text,'peux'::text,'peux'::text,'suis'::text,'En volant aussi haut, je peux voir la petite route en bas.'::text),
(299825,33314,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bu kadar yüksekte uçarken ben aşağıdaki küçük yolu ...'::text,'görebilirim'::text,'görebilirim'::text,NULL::text,'Bu kadar yüksekte uçarken ben aşağıdaki küçük yolu görebilirim.'::text),
(299826,33314,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ilyen magasan repülve én ... látni a kis utat odalent.'::text,'tudom'::text,'tudom'::text,'vagyok'::text,'Ilyen magasan repülve én tudom látni a kis utat odalent.'::text),
(299829,33315,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ganz ehrlich, du fliegst hoch, sogar ... als die Kiefern.'::text,'höher'::text,'höher'::text,'am höchsten'::text,'Ganz ehrlich, du fliegst hoch, sogar höher als die Kiefern.'::text),
(299833,33315,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Не буду брехати, ти летиш високо, навіть ... за сосни.'::text,'вище'::text,'більш високо'::text,'найвище'::text,'Не буду брехати, ти летиш високо, навіть вище за сосни.'::text),
(299832,33315,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'No voy a mentir, tú vuelas alto, incluso ... que los pinos.'::text,'más alto'::text,'más alto'::text,'lo más alto'::text,'No voy a mentir, tú vuelas alto, incluso más alto que los pinos.'::text),
(299831,33315,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Je vais pas mentir, tu voles haut, même ... que les pins.'::text,'plus haut'::text,'plus haut'::text,'le plus haut'::text,'Je vais pas mentir, tu voles haut, même plus haut que les pins.'::text),
(299834,33315,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yalan yok, sen yüksekten uçuyorsun, hatta çamlardan bile ...'::text,'daha yüksekten'::text,'daha yüksekten'::text,'en yüksekten'::text,'Yalan yok, sen yüksekten uçuyorsun, hatta çamlardan bile daha yüksekten.'::text),
(299835,33315,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nem hazudok, te magasan repülsz, még a fenyőknél is ...'::text,'magasabban'::text,'magasabban'::text,'legmagasabban'::text,'Nem hazudok, te magasan repülsz, még a fenyőknél is magasabban.'::text),
(295761,32863,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... Front hier hat einen runden Chromscheinwerfer.'::text,'Diese'::text,'Diese'::text,'Jene'::text,'Diese Front hier hat einen runden Chromscheinwerfer.'::text),
(295765,32863,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... передок тут має круглу хромовану фару.'::text,'Цей'::text,'Ці'::text,'Ті'::text,'Цей передок тут має круглу хромовану фару.'::text),
(295764,32863,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... frontal de aquí tiene un faro cromado redondo.'::text,'Este'::text,'Estos'::text,'Esos'::text,'Este frontal de aquí tiene un faro cromado redondo.'::text),
(295763,32863,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... avant, ici, a un phare rond chromé.'::text,'Cet'::text,'Ces'::text,'Ces'::text,'Cet avant, ici, a un phare rond chromé.'::text),
(295766,32863,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... ön kısmın burada yuvarlak krom bir farı var.'::text,'Bu'::text,'Bu'::text,'Şu'::text,'Bu ön kısmın burada yuvarlak krom bir farı var.'::text),
(295767,32863,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... az elejének itt kerek krómozott fényszórója van.'::text,'Ennek'::text,'Ezeknek'::text,'Azoknak'::text,'Ennek az elejének itt kerek krómozott fényszórója van.'::text),
(295797,32867,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Katastrophe! Vorne am alten Auto ist nicht viel ... übrig!'::text,'Farbe'::text,'Farbe'::text,'Lichter'::text,'Katastrophe! Vorne am alten Auto ist nicht viel Farbe übrig!'::text),
(295801,32867,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Катастрофа! На передку старої машини залишилося небагато ...!'::text,'фарби'::text,'фарб'::text,'фар'::text,'Катастрофа! На передку старої машини залишилося небагато фарби!'::text),
(295800,32867,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Desastre! ¡No queda mucha ... en la parte delantera del coche viejo!'::text,'pintura'::text,'pintura'::text,'luces'::text,'¡Desastre! ¡No queda mucha pintura en la parte delantera del coche viejo!'::text),
(295799,32867,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Catastrophe ! Il ne reste pas beaucoup de ... sur l''avant de la vieille voiture !'::text,'peinture'::text,'peinture'::text,'phares'::text,'Catastrophe ! Il ne reste pas beaucoup de peinture sur l''avant de la vieille voiture !'::text),
(295802,32867,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Felaket! Eski arabanın önünde çok ... kalmamış!'::text,'boya'::text,'boyalar'::text,'far'::text,'Felaket! Eski arabanın önünde çok boya kalmamış!'::text),
(295803,32867,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Katasztrófa! Nem sok ... maradt a régi autó elején!'::text,'festék'::text,'festék'::text,'lámpa'::text,'Katasztrófa! Nem sok festék maradt a régi autó elején!'::text),
(321843,35761,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er liebt das Auto, aber er ... auch über andere Dinge reden.'::text,'sollte'::text,'sollte'::text,'soll'::text,'Er liebt das Auto, aber er sollte auch über andere Dinge reden.'::text),
(321847,35761,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він любить цю машину, але він ... говорити й про інше.'::text,'мав би'::text,'мав би'::text,'буде'::text,'Він любить цю машину, але він мав би говорити й про інше.'::text),
(321846,35761,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Él adora el coche, pero ... hablar también de otras cosas.'::text,'debería'::text,'debería'::text,'deberá'::text,'Él adora el coche, pero debería hablar también de otras cosas.'::text),
(321845,35761,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il adore la voiture, mais il ... parler d''autres choses aussi.'::text,'devrait'::text,'devrait'::text,'devra'::text,'Il adore la voiture, mais il devrait parler d''autres choses aussi.'::text),
(321848,35761,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O arabayı seviyor ama başka şeylerden de ...'::text,'konuşmalı'::text,'konuşmalı'::text,'konuşacak'::text,'O arabayı seviyor ama başka şeylerden de konuşmalı.'::text),
(321849,35761,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ő imádja az autót, de más dolgokról is ... beszélnie.'::text,'kellene'::text,'kellene'::text,'kell'::text,'Ő imádja az autót, de más dolgokról is kellene beszélnie.'::text),
(318648,35406,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Alter, er ... Speed auf Bergstraßen, gleich gibt er Gas.'::text,'liebt'::text,'lieben'::text,'liebend'::text,'Alter, er liebt Speed auf Bergstraßen, gleich gibt er Gas.'::text),
(318652,35406,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бро, він ... швидкість на гірських дорогах, зараз як дасть газу.'::text,'любить'::text,'любити'::text,'люблячи'::text,'Бро, він любить швидкість на гірських дорогах, зараз як дасть газу.'::text),
(318651,35406,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tío, él ... la velocidad en carreteras de montaña, va a ir a tope.'::text,'ama'::text,'amar'::text,'amando'::text,'Tío, él ama la velocidad en carreteras de montaña, va a ir a tope.'::text),
(318650,35406,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Frérot, il ... la vitesse sur les routes de montagne, il va foncer.'::text,'adore'::text,'adorer'::text,'adorant'::text,'Frérot, il adore la vitesse sur les routes de montagne, il va foncer.'::text),
(318653,35406,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, o dağ yollarında hızı ..., gazlayacak.'::text,'sever'::text,'sevmek'::text,'severek'::text,'Kanka, o dağ yollarında hızı sever, gazlayacak.'::text),
(318654,35406,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, ő ... a sebességet a hegyi utakon, mindjárt padlógázzal megy.'::text,'imádja'::text,'imádni'::text,'imádó'::text,'Tesó, ő imádja a sebességet a hegyi utakon, mindjárt padlógázzal megy.'::text),
(318693,35411,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Okay, also er hat mir gesagt, dass er in der Stadt nicht mit ... Tempo fährt.'::text,'viel'::text,'vielen'::text,'ein paar'::text,'Okay, also er hat mir gesagt, dass er in der Stadt nicht mit viel Tempo fährt.'::text),
(318697,35411,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Коротше, він мені сказав, що не їздить у місті з ... швидкістю.'::text,'великою'::text,'великою'::text,'кількома'::text,'Коротше, він мені сказав, що не їздить у місті з великою швидкістю.'::text),
(318696,35411,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Vale, él me dijo que no conduce a ... velocidad por la ciudad.'::text,'mucha'::text,'muchas'::text,'unas pocas'::text,'Vale, él me dijo que no conduce a mucha velocidad por la ciudad.'::text),
(318695,35411,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bon, il m''a dit qu''il ne roule pas à ... vitesse en ville.'::text,'grande'::text,'grande'::text,'quelques'::text,'Bon, il m''a dit qu''il ne roule pas à grande vitesse en ville.'::text),
(318698,35411,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bak şimdi, o bana şehirde ... hızla sürmediğini söyledi.'::text,'çok'::text,'çok'::text,'birkaç'::text,'Bak şimdi, o bana şehirde çok hızla sürmediğini söyledi.'::text),
(318699,35411,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Szóval ő azt mondta nekem, hogy a városban nem megy ... sebességgel.'::text,'nagy'::text,'nagy'::text,'pár'::text,'Szóval ő azt mondta nekem, hogy a városban nem megy nagy sebességgel.'::text),
(317298,35256,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... läuft die langsame Schildkröte? Tag und Nacht.'::text,'Wann'::text,'Wer'::text,'Warum'::text,'Wann läuft die langsame Schildkröte? Tag und Nacht.'::text),
(317302,35256,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... іде повільна черепаха? Удень і вночі.'::text,'Коли'::text,'Хто'::text,'Чому'::text,'Коли іде повільна черепаха? Удень і вночі.'::text),
(317301,35256,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¿... camina la tortuga lenta? Día y noche.'::text,'Cuándo'::text,'Quién'::text,'Por qué'::text,'¿Cuándo camina la tortuga lenta? Día y noche.'::text),
(317300,35256,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... la tortue lente marche-t-elle ? Jour et nuit.'::text,'Quand'::text,'Qui'::text,'Pourquoi'::text,'Quand la tortue lente marche-t-elle ? Jour et nuit.'::text),
(317303,35256,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yavaş kaplumbağa ... yürüyor? Gece gündüz.'::text,'ne zaman'::text,'kim'::text,'neden'::text,'Yavaş kaplumbağa ne zaman yürüyor? Gece gündüz.'::text),
(317304,35256,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... megy a lassú teknős? Éjjel-nappal.'::text,'Mikor'::text,'Ki'::text,'Miért'::text,'Mikor megy a lassú teknős? Éjjel-nappal.'::text),
(317352,35262,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Alter, die Schildkröte läuft so ..., eher mid, aber sie gewinnt.'::text,'langsam'::text,'langsam'::text,'Langsamkeit'::text,'Alter, die Schildkröte läuft so langsam, eher mid, aber sie gewinnt.'::text),
(317356,35262,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чувак, черепаха йде так ..., таке собі, але вона виграє.'::text,'повільно'::text,'повільно'::text,'повільність'::text,'Чувак, черепаха йде так повільно, таке собі, але вона виграє.'::text),
(317355,35262,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tío, la tortuga camina tan ..., bastante meh, pero gana.'::text,'lentamente'::text,'lentamente'::text,'lentitud'::text,'Tío, la tortuga camina tan lentamente, bastante meh, pero gana.'::text),
(317354,35262,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mec, la tortue marche si ..., un peu bof, mais elle gagne.'::text,'lentement'::text,'lentement'::text,'lenteur'::text,'Mec, la tortue marche si lentement, un peu bof, mais elle gagne.'::text),
(317357,35262,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, kaplumbağa o kadar ... yürüyor ki, vasat ama kazanıyor.'::text,'yavaşça'::text,'yavaşça'::text,'yavaşlık'::text,'Kanka, kaplumbağa o kadar yavaşça yürüyor ki, vasat ama kazanıyor.'::text),
(317358,35262,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Haver, a teknős olyan ... megy, elég gyenge, de nyer.'::text,'lassan'::text,'lassan'::text,'lassúság'::text,'Haver, a teknős olyan lassan megy, elég gyenge, de nyer.'::text),
(304221,33803,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Alter, ein Blick auf zwei ... und ich schrei gleich.'::text,'Bären'::text,'Bär'::text,'Bären'::text,'Alter, ein Blick auf zwei Bären und ich schrei gleich.'::text),
(304225,33803,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бро, один погляд на двох ... — і я закричу.'::text,'ведмедів'::text,'ведмедя'::text,'ведмедів'::text,'Бро, один погляд на двох ведмедів — і я закричу.'::text),
(304224,33803,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tío, una mirada a dos ... y yo me pongo a gritar.'::text,'osos'::text,'oso'::text,'osos'::text,'Tío, una mirada a dos osos y yo me pongo a gritar.'::text),
(304223,33803,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Frérot, un regard sur deux ... et je vais hurler.'::text,'ours'::text,'ours'::text,'ours'::text,'Frérot, un regard sur deux ours et je vais hurler.'::text),
(304226,33803,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, iki ... bir bakış, ben de çığlığı basacağım.'::text,'ayıya'::text,'ayıya'::text,'ayılara'::text,'Kanka, iki ayıya bir bakış, ben de çığlığı basacağım.'::text),
(304227,33803,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, egy pillantás a két ..., és én sikítani fogok.'::text,'medvére'::text,'medvére'::text,'medvére'::text,'Tesó, egy pillantás a két medvére, és én sikítani fogok.'::text),
(314301,34923,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Henne ... ihr Küken aus dem eisigen Wasser.'::text,'rettet'::text,'retten'::text,'rettend'::text,'Die Henne rettet ihr Küken aus dem eisigen Wasser.'::text),
(314305,34923,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Курка ... своє курча з крижаної води.'::text,'рятує'::text,'рятувати'::text,'рятуючи'::text,'Курка рятує своє курча з крижаної води.'::text),
(314304,34923,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La gallina ... a su pollito del agua helada.'::text,'salva'::text,'salvar'::text,'salvando'::text,'La gallina salva a su pollito del agua helada.'::text),
(314303,34923,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La poule ... son poussin de l''eau glacée.'::text,'sauve'::text,'sauver'::text,'sauvant'::text,'La poule sauve son poussin de l''eau glacée.'::text),
(314306,34923,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tavuk civcivini buz gibi sudan ...'::text,'kurtarır'::text,'kurtarmak'::text,'kurtararak'::text,'Tavuk civcivini buz gibi sudan kurtarır.'::text),
(314307,34923,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A tyúk ... a csibéjét a jeges vízből.'::text,'kimenti'::text,'kimenteni'::text,'kimentő'::text,'A tyúk kimenti a csibéjét a jeges vízből.'::text),
(314337,34927,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yo, die Henne taucht rein, sie ... das Küken retten, echt.'::text,'wird'::text,'wird'::text,NULL::text,'Yo, die Henne taucht rein, sie wird das Küken retten, echt.'::text),
(314341,34927,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Йо, курка пірнає, вона ... те курча, серйозно.'::text,'збирається врятувати'::text,'врятує'::text,NULL::text,'Йо, курка пірнає, вона збирається врятувати те курча, серйозно.'::text),
(314340,34927,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Oye, la gallina se lanza, ella ... a ese pollito, en serio.'::text,'va a salvar'::text,'salvará'::text,NULL::text,'Oye, la gallina se lanza, ella va a salvar a ese pollito, en serio.'::text),
(314339,34927,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yo, la poule plonge, elle ... ce poussin, sérieux.'::text,'va sauver'::text,'sauvera'::text,NULL::text,'Yo, la poule plonge, elle va sauver ce poussin, sérieux.'::text),
(314342,34927,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, tavuk suya dalıyor, o şu civcivi ..., cidden.'::text,'kurtaracak'::text,'kurtaracak'::text,NULL::text,'Kanka, tavuk suya dalıyor, o şu civcivi kurtaracak, cidden.'::text),
(314343,34927,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, a tyúk beugrik, ő meg ... menteni azt a csibét, komolyan.'::text,'fogja'::text,'fogja'::text,NULL::text,'Tesó, a tyúk beugrik, ő meg fogja menteni azt a csibét, komolyan.'::text),
(305868,33986,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Gestern Abend ... die Küken ihre Schnäbel weit für das Korn der Henne.'::text,'öffneten'::text,'öffnet'::text,'öffnend'::text,'Gestern Abend öffneten die Küken ihre Schnäbel weit für das Korn der Henne.'::text),
(305872,33986,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Минулого вечора пташенята широко ... дзьобики для зерна курки.'::text,'відкрили'::text,'відкриває'::text,'відкриваючи'::text,'Минулого вечора пташенята широко відкрили дзьобики для зерна курки.'::text),
(305871,33986,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Anoche los polluelos ... mucho el pico para el grano de la gallina.'::text,'abrieron'::text,'abre'::text,'abriendo'::text,'Anoche los polluelos abrieron mucho el pico para el grano de la gallina.'::text),
(305870,33986,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hier soir, les oisillons ... grand le bec pour le grain de la poule.'::text,'ont ouvert'::text,'ouvre'::text,'ouvrant'::text,'Hier soir, les oisillons ont ouvert grand le bec pour le grain de la poule.'::text),
(305873,33986,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dün gece yavrular tavuğun tanesi için ağızlarını kocaman ...'::text,'açtı'::text,'açar'::text,'açarak'::text,'Dün gece yavrular tavuğun tanesi için ağızlarını kocaman açtı.'::text),
(305874,33986,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tegnap este a fiókák szélesre ... a csőrüket a tyúk magjáért.'::text,'tátották'::text,'tátja'::text,'tátó'::text,'Tegnap este a fiókák szélesre tátották a csőrüket a tyúk magjáért.'::text),
(306930,34104,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... ich dir einen Kuchen anbieten? Es ist Kuchen, also ja.'::text,'Kann'::text,NULL::text,'Bin'::text,'Kann ich dir einen Kuchen anbieten? Es ist Kuchen, also ja.'::text),
(306934,34104,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чи ... я запропонувати тобі торт? Це торт, тож так.'::text,'можу'::text,NULL::text,'є'::text,'Чи можу я запропонувати тобі торт? Це торт, тож так.'::text),
(306933,34104,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¿... yo ofrecerte una tarta? Es tarta, así que sí.'::text,'Puedo'::text,NULL::text,'Estoy'::text,'¿Puedo yo ofrecerte una tarta? Es tarta, así que sí.'::text),
(306932,34104,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Est-ce que je ... t''offrir un gâteau ? C''est du gâteau, donc oui.'::text,'peux'::text,NULL::text,'suis'::text,'Est-ce que je peux t''offrir un gâteau ? C''est du gâteau, donc oui.'::text),
(306935,34104,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ben sana bir pasta ... miyim? Bu pasta, yani evet.'::text,'ikram edebilir'::text,NULL::text,NULL::text,'Ben sana bir pasta ikram edebilir miyim? Bu pasta, yani evet.'::text),
(306936,34104,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... én neked egy tortát? Ez torta, szóval igen.'::text,'Kínálhatok'::text,NULL::text,'Vagyok'::text,'Kínálhatok én neked egy tortát? Ez torta, szóval igen.'::text),
(306975,34109,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Alter, du ... ihr den Kuchen anbieten und sie nicht hinterherjagen lassen, echt.'::text,'solltest'::text,'solltest'::text,'solltest'::text,'Alter, du solltest ihr den Kuchen anbieten und sie nicht hinterherjagen lassen, echt.'::text),
(306979,34109,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бро, ти ... запропонувати їй торт, а не змушувати її ганятися за ним, серйозно.'::text,'мав би'::text,'мав би'::text,'мав би'::text,'Бро, ти мав би запропонувати їй торт, а не змушувати її ганятися за ним, серйозно.'::text),
(306978,34109,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tío, tú ... ofrecerle la tarta, no hacer que la persiga, en serio.'::text,'deberías'::text,'deberías'::text,'deberías'::text,'Tío, tú deberías ofrecerle la tarta, no hacer que la persiga, en serio.'::text),
(306977,34109,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Frérot, tu ... lui offrir le gâteau, pas la faire courir après, sérieux.'::text,'devrais'::text,'devrais'::text,'devrais'::text,'Frérot, tu devrais lui offrir le gâteau, pas la faire courir après, sérieux.'::text),
(306980,34109,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, sen pastayı ona ..., peşinden koşturmamalısın, cidden.'::text,'ikram etmelisin'::text,'ikram etmelisin'::text,'ikram etmelisin'::text,'Kanka, sen pastayı ona ikram etmelisin, peşinden koşturmamalısın, cidden.'::text),
(306981,34109,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, neked ... felkínálnod neki a tortát, nem pedig futtatni utána, komolyan.'::text,'kellene'::text,'kellene'::text,'kellene'::text,'Tesó, neked kellene felkínálnod neki a tortát, nem pedig futtatni utána, komolyan.'::text),
(307875,34209,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er hat einen Plan. Er ... eine Botschaft auf den Rasen malen.'::text,'wird'::text,'wird'::text,'malt'::text,'Er hat einen Plan. Er wird eine Botschaft auf den Rasen malen.'::text),
(307879,34209,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'У нього є план. Він ... послання на газоні.'::text,'збирається намалювати'::text,'намалює'::text,'малює'::text,'У нього є план. Він збирається намалювати послання на газоні.'::text),
(307878,34209,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tiene un plan. Él ... un mensaje en el césped.'::text,'va a pintar'::text,'pintará'::text,'pinta'::text,'Tiene un plan. Él va a pintar un mensaje en el césped.'::text),
(307877,34209,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il a un plan. Il ... un message sur la pelouse.'::text,'va peindre'::text,'peindra'::text,'peint'::text,'Il a un plan. Il va peindre un message sur la pelouse.'::text),
(307880,34209,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Onun bir planı var. O çimlere bir mesaj ...'::text,'boyayacak'::text,'boyayacak'::text,'boyar'::text,'Onun bir planı var. O çimlere bir mesaj boyayacak.'::text),
(307881,34209,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Van egy terve. Ő egy üzenetet ... festeni a gyepre.'::text,'fog'::text,'fog'::text,'fest'::text,'Van egy terve. Ő egy üzenetet fog festeni a gyepre.'::text),
(296787,32977,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Alter, Oma macht gleich ... da drüben auf.'::text,'jenes Geschenk'::text,'jene Geschenke'::text,'diese Geschenke'::text,'Alter, Oma macht gleich jenes Geschenk da drüben auf.'::text),
(296791,32977,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бро, бабуся зараз відкриє ... онде.'::text,'той подарунок'::text,'той подарунок'::text,'цей подарунок'::text,'Бро, бабуся зараз відкриє той подарунок онде.'::text),
(296790,32977,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tío, la abuela va a abrir ... de allí.'::text,'ese regalo'::text,'esos regalos'::text,'estos regalos'::text,'Tío, la abuela va a abrir ese regalo de allí.'::text),
(296789,32977,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Frérot, mamie va ouvrir ... là-bas.'::text,'ce cadeau'::text,'ces cadeaux'::text,'ces cadeaux'::text,'Frérot, mamie va ouvrir ce cadeau là-bas.'::text),
(296792,32977,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, nine oradaki ... açacak.'::text,'şu hediyeyi'::text,'şu hediyeyi'::text,'bu hediyeyi'::text,'Kanka, nine oradaki şu hediyeyi açacak.'::text),
(296793,32977,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, a mama mindjárt kinyitja ... ott.'::text,'azt az ajándékot'::text,'azokat az ajándékokat'::text,'ezeket az ajándékokat'::text,'Tesó, a mama mindjárt kinyitja azt az ajándékot ott.'::text),
(296814,32980,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Unglaublich! Es gibt nicht ... Geschenke, die so groß sind wie Oma!'::text,'viele'::text,'viel'::text,'einige'::text,'Unglaublich! Es gibt nicht viele Geschenke, die so groß sind wie Oma!'::text),
(296818,32980,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Неймовірно! Немає ... подарунків, таких великих, як бабуся!'::text,'багато'::text,'багато'::text,'якихось'::text,'Неймовірно! Немає багато подарунків, таких великих, як бабуся!'::text),
(296817,32980,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Increíble! ¡No hay ... regalos tan grandes como la abuela!'::text,'muchos'::text,'mucho'::text,'algunos'::text,'¡Increíble! ¡No hay muchos regalos tan grandes como la abuela!'::text),
(296816,32980,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Incroyable ! Il n''y a pas ... cadeaux aussi grands que mamie !'::text,'beaucoup de'::text,'beaucoup de'::text,'des'::text,'Incroyable ! Il n''y a pas beaucoup de cadeaux aussi grands que mamie !'::text),
(296819,32980,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'İnanılmaz! Nine kadar büyük ... hediye yok!'::text,'çok'::text,'çok'::text,'bazı'::text,'İnanılmaz! Nine kadar büyük çok hediye yok!'::text),
(296820,32980,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hihetetlen! Nincs ... olyan nagy ajándék, mint a mama!'::text,'sok'::text,'sok'::text,'néhány'::text,'Hihetetlen! Nincs sok olyan nagy ajándék, mint a mama!'::text),
(312825,34759,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... bringt dein Hund die Bälle so schnell zurück? Ehrlich, beeindruckt.'::text,'Wie'::text,'Wer'::text,'Wo'::text,'Wie bringt dein Hund die Bälle so schnell zurück? Ehrlich, beeindruckt.'::text),
(312829,34759,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... твій пес так швидко повертає м''ячі? Чесно, вражає.'::text,'Як'::text,'Хто'::text,'Де'::text,'Як твій пес так швидко повертає м''ячі? Чесно, вражає.'::text),
(312828,34759,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¿... devuelve tu perro las pelotas tan rápido? En serio, impresionado.'::text,'Cómo'::text,'Quién'::text,'Dónde'::text,'¿Cómo devuelve tu perro las pelotas tan rápido? En serio, impresionado.'::text),
(312827,34759,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... ton chien rapporte-t-il les balles si vite ? Franchement, impressionné.'::text,'Comment'::text,'Qui'::text,'Où'::text,'Comment ton chien rapporte-t-il les balles si vite ? Franchement, impressionné.'::text),
(312830,34759,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Senin köpeğin topları ... bu kadar hızlı geri getiriyor? Açıkçası etkilendim.'::text,'nasıl'::text,'kim'::text,'nerede'::text,'Senin köpeğin topları nasıl bu kadar hızlı geri getiriyor? Açıkçası etkilendim.'::text),
(312831,34759,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... hozza vissza a kutyád ilyen gyorsan a labdákat? Őszintén, le vagyok nyűgözve.'::text,'Hogyan'::text,'Ki'::text,'Hol'::text,'Hogyan hozza vissza a kutyád ilyen gyorsan a labdákat? Őszintén, le vagyok nyűgözve.'::text),
(312834,34760,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ehrlich, dein Hund ... gestern jeden Ball zur Maschine zurück. Respekt.'::text,'brachte'::text,'bringt'::text,'bringen'::text,'Ehrlich, dein Hund brachte gestern jeden Ball zur Maschine zurück. Respekt.'::text),
(312838,34760,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чесно, твій пес учора ... кожен м''яч до машини. Респект.'::text,'повернув'::text,'повертає'::text,'повертати'::text,'Чесно, твій пес учора повернув кожен м''яч до машини. Респект.'::text),
(312837,34760,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'En serio, tu perro ... cada pelota a la máquina ayer. Respeto.'::text,'devolvió'::text,'devuelve'::text,'devolver'::text,'En serio, tu perro devolvió cada pelota a la máquina ayer. Respeto.'::text),
(312836,34760,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Franchement, ton chien ... chaque balle à la machine hier. Respect.'::text,'a rapporté'::text,'rapporte'::text,'rapporter'::text,'Franchement, ton chien a rapporté chaque balle à la machine hier. Respect.'::text),
(312839,34760,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Açıkçası senin köpeğin dün her topu makineye geri ...; saygılar.'::text,'getirdi'::text,'getirir'::text,'getirmek'::text,'Açıkçası senin köpeğin dün her topu makineye geri getirdi; saygılar.'::text),
(312840,34760,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Őszintén, a kutyád tegnap minden labdát ... a géphez. Respekt.'::text,'visszavitt'::text,'visszavisz'::text,'visszavinni'::text,'Őszintén, a kutyád tegnap minden labdát visszavitt a géphez. Respekt.'::text),
(305058,33896,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... trifft die Katze den Löwen? An den Gitterstäben im Zoo.'::text,'Wo'::text,'Wann'::text,'Wer'::text,'Wo trifft die Katze den Löwen? An den Gitterstäben im Zoo.'::text),
(305062,33896,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... кішка зустрічається з левом? Біля ґрат у зоопарку.'::text,'Де'::text,'Коли'::text,'Хто'::text,'Де кішка зустрічається з левом? Біля ґрат у зоопарку.'::text),
(305061,33896,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¿... se encuentra el gato con el león? En los barrotes del zoo.'::text,'Dónde'::text,'Cuándo'::text,'Quién'::text,'¿Dónde se encuentra el gato con el león? En los barrotes del zoo.'::text),
(305060,33896,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... le chat rencontre-t-il le lion ? Aux barreaux du zoo.'::text,'Où'::text,'Quand'::text,'Qui'::text,'Où le chat rencontre-t-il le lion ? Aux barreaux du zoo.'::text),
(305063,33896,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kedi aslanla ... karşılaşıyor? Hayvanat bahçesinin parmaklıklarında.'::text,'nerede'::text,'ne zaman'::text,'kim'::text,'Kedi aslanla nerede karşılaşıyor? Hayvanat bahçesinin parmaklıklarında.'::text),
(305064,33896,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... találkozik a macska az oroszlánnal? Az állatkert rácsánál.'::text,'Hol'::text,'Mikor'::text,'Ki'::text,'Hol találkozik a macska az oroszlánnal? Az állatkert rácsánál.'::text),
(305085,33899,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Katze ... den Löwen jetzt, weil sie am selben Ort sind.'::text,'trifft'::text,'trifft'::text,'trifft'::text,'Die Katze trifft den Löwen jetzt, weil sie am selben Ort sind.'::text),
(305089,33899,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Кішка зараз ... лева, бо вони в одному місці.'::text,'зустрічає'::text,'зустрічає'::text,'зустрічає'::text,'Кішка зараз зустрічає лева, бо вони в одному місці.'::text),
(305088,33899,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El gato ... con el león ahora porque están en el mismo sitio.'::text,'se está encontrando'::text,'se encuentra'::text,'se está encontrando'::text,'El gato se está encontrando con el león ahora porque están en el mismo sitio.'::text),
(305087,33899,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le chat ... le lion maintenant parce qu''ils sont au même endroit.'::text,'est en train de rencontrer'::text,'rencontre'::text,'est en train de rencontrer'::text,'Le chat est en train de rencontrer le lion maintenant parce qu''ils sont au même endroit.'::text),
(305090,33899,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kedi şu an aslanla ... çünkü aynı yerdeler.'::text,'buluşuyor'::text,'buluşur'::text,'buluşuyor'::text,'Kedi şu an aslanla buluşuyor çünkü aynı yerdeler.'::text),
(305091,33899,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A macska most ... az oroszlánnal, mert ugyanott vannak.'::text,'találkozik'::text,'találkozik'::text,'találkozik'::text,'A macska most találkozik az oroszlánnal, mert ugyanott vannak.'::text),
(323967,35997,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Alter, die Rakete ... über ihm auf, so riesig, da muss man springen.'::text,'ragt'::text,'ragen'::text,'ragend'::text,'Alter, die Rakete ragt über ihm auf, so riesig, da muss man springen.'::text),
(323971,35997,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бро, ракета ... над ним, така величезна, треба стрибати.'::text,'височіє'::text,'височіти'::text,'височіючи'::text,'Бро, ракета височіє над ним, така величезна, треба стрибати.'::text),
(323970,35997,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tío, el cohete se ... sobre él, enorme, hay que saltar.'::text,'alza'::text,'alzar'::text,'alzando'::text,'Tío, el cohete se alza sobre él, enorme, hay que saltar.'::text),
(323969,35997,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Frérot, la fusée ... au-dessus de lui, trop énorme, faut sauter.'::text,'se dresse'::text,'se dresser'::text,'se dressant'::text,'Frérot, la fusée se dresse au-dessus de lui, trop énorme, faut sauter.'::text),
(323972,35997,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, roket onun üstünde ..., çok büyük, zıplamak lazım.'::text,'yükselir'::text,'yükselmek'::text,'yükselerek'::text,'Kanka, roket onun üstünde yükselir, çok büyük, zıplamak lazım.'::text),
(323973,35997,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, a rakéta ... fölötte, akkora, hogy ugrálni kell.'::text,'tornyosul'::text,'tornyosulni'::text,'tornyosuló'::text,'Tesó, a rakéta tornyosul fölötte, akkora, hogy ugrálni kell.'::text),
(324021,36003,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Man sagt, die Rakete ragt über ihm auf. Er ... ein Selfie machen, Mädel.'::text,'sollte'::text,'sollte'::text,'soll'::text,'Man sagt, die Rakete ragt über ihm auf. Er sollte ein Selfie machen, Mädel.'::text),
(324025,36003,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Кажуть, ракета височіє над ним. Він ... зробити селфі, подруго.'::text,'мав би'::text,'мав би'::text,'буде'::text,'Кажуть, ракета височіє над ним. Він мав би зробити селфі, подруго.'::text),
(324024,36003,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dicen que el cohete se alza sobre él. Él ... hacerse un selfie, tía.'::text,'debería'::text,'debería'::text,'deberá'::text,'Dicen que el cohete se alza sobre él. Él debería hacerse un selfie, tía.'::text),
(324023,36003,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il paraît que la fusée le domine. Il ... prendre un selfie, ma belle.'::text,'devrait'::text,'devrait'::text,'devra'::text,'Il paraît que la fusée le domine. Il devrait prendre un selfie, ma belle.'::text),
(324026,36003,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dediklerine göre roket onun üstünde yükseliyormuş. O bir selfie ..., kızım.'::text,'çekmeli'::text,'çekmeli'::text,'çekecek'::text,'Dediklerine göre roket onun üstünde yükseliyormuş. O bir selfie çekmeli, kızım.'::text),
(324027,36003,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Azt beszélik, a rakéta föléje tornyosul. Neki ... csinálnia egy szelfit, csajszi.'::text,'kellene'::text,'kellene'::text,'kell'::text,'Azt beszélik, a rakéta föléje tornyosul. Neki kellene csinálnia egy szelfit, csajszi.'::text),
(313185,34799,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Das Wochenziel sind ... Fahrten im winzigen pinken Jeep.'::text,'sieben'::text,'siebte'::text,'Siebenen'::text,'Das Wochenziel sind sieben Fahrten im winzigen pinken Jeep.'::text),
(313189,34799,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Тижнева ціль — ... поїздок у крихітному рожевому джипі.'::text,'сім'::text,'сьома'::text,'сімки'::text,'Тижнева ціль — сім поїздок у крихітному рожевому джипі.'::text),
(313188,34799,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El objetivo semanal es ... paseos en el diminuto todoterreno rosa.'::text,'siete'::text,'séptimo'::text,'siete'::text,'El objetivo semanal es siete paseos en el diminuto todoterreno rosa.'::text),
(313187,34799,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'L''objectif de la semaine est de ... tours dans la minuscule jeep rose.'::text,'sept'::text,'septième'::text,'sept'::text,'L''objectif de la semaine est de sept tours dans la minuscule jeep rose.'::text),
(313190,34799,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Haftalık hedef minicik pembe cipte ... tur.'::text,'yedi'::text,'yedinci'::text,'yediler'::text,'Haftalık hedef minicik pembe cipte yedi tur.'::text),
(313191,34799,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A heti cél ... kör a pici rózsaszín terepjáróban.'::text,'hét'::text,'hetedik'::text,'hetesek'::text,'A heti cél hét kör a pici rózsaszín terepjáróban.'::text),
(313194,34800,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Jeep ist pink. Deshalb macht ihre Fahrt so viel ...'::text,'Spaß'::text,'Spaß'::text,'einen Spaß'::text,'Der Jeep ist pink. Deshalb macht ihre Fahrt so viel Spaß.'::text),
(313198,34800,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Джип рожевий. Тому в її поїздці стільки ...'::text,'веселощів'::text,'веселощів'::text,'веселощів'::text,'Джип рожевий. Тому в її поїздці стільки веселощів.'::text),
(313197,34800,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El todoterreno es rosa. Por eso su paseo da tanta ...'::text,'diversión'::text,'diversión'::text,'una diversión'::text,'El todoterreno es rosa. Por eso su paseo da tanta diversión.'::text),
(313196,34800,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La jeep est rose. C''est pour ça que sa balade apporte tellement de ...'::text,'plaisir'::text,'plaisir'::text,'un plaisir'::text,'La jeep est rose. C''est pour ça que sa balade apporte tellement de plaisir.'::text),
(313199,34800,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Cip pembe. Bu yüzden onun turunda o kadar çok ... var.'::text,'eğlence'::text,'eğlenceler'::text,'bir eğlence'::text,'Cip pembe. Bu yüzden onun turunda o kadar çok eğlence var.'::text),
(313200,34800,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A terepjáró rózsaszín. Ezért olyan nagy ... az útja.'::text,'móka'::text,'móka'::text,'egy móka'::text,'A terepjáró rózsaszín. Ezért olyan nagy móka az útja.'::text),
(302880,33654,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Du ... spät dran, aber ehrlich, du rennst so schnell.'::text,'bist'::text,'ist'::text,'bin'::text,'Du bist spät dran, aber ehrlich, du rennst so schnell.'::text),
(302884,33654,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ти ... із запізненням, але чесно, ти так швидко бігаєш.'::text,'є'::text,'є'::text,'є'::text,'Ти є із запізненням, але чесно, ти так швидко бігаєш.'::text),
(302883,33654,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tú ... retrasado, pero en serio, corres rapidísimo.'::text,'estás'::text,'está'::text,'estoy'::text,'Tú estás retrasado, pero en serio, corres rapidísimo.'::text),
(302882,33654,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tu ... en retard, mais franchement, tu cours si vite.'::text,'es'::text,'est'::text,'suis'::text,'Tu es en retard, mais franchement, tu cours si vite.'::text),
(302885,33654,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sen geç ..., ama açıkçası çok hızlı koşuyorsun.'::text,'kaldın'::text,'kaldı'::text,'kaldım'::text,'Sen geç kaldın, ama açıkçası çok hızlı koşuyorsun.'::text),
(302886,33654,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Te ... késésben, de őszintén, olyan gyorsan futsz.'::text,'vagy'::text,NULL::text,'vagyok'::text,'Te vagy késésben, de őszintén, olyan gyorsan futsz.'::text),
(302889,33655,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Es ist schon 10:50. Ehrlich, du ... zu spät sein, aber mit Selbstvertrauen.'::text,'wirst'::text,'wirst'::text,'wird'::text,'Es ist schon 10:50. Ehrlich, du wirst zu spät sein, aber mit Selbstvertrauen.'::text),
(302893,33655,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Уже 10:50. Чесно, ти ..., але впевнено.'::text,'збираєшся запізнитися'::text,'запізнишся'::text,'збирається запізнитися'::text,'Уже 10:50. Чесно, ти збираєшся запізнитися, але впевнено.'::text),
(302892,33655,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ya son las 10:50. En serio, tú ... tarde, pero con confianza.'::text,'vas a llegar'::text,'llegarás'::text,'va a llegar'::text,'Ya son las 10:50. En serio, tú vas a llegar tarde, pero con confianza.'::text),
(302891,33655,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il est déjà 10 h 50. Franchement, tu ... en retard, mais avec assurance.'::text,'vas être'::text,'seras'::text,'va être'::text,'Il est déjà 10 h 50. Franchement, tu vas être en retard, mais avec assurance.'::text),
(302894,33655,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Saat şimdiden 10:50. Açıkçası sen ... ama özgüvenle.'::text,'geç kalacaksın'::text,'geç kalacaksın'::text,'geç kalacak'::text,'Saat şimdiden 10:50. Açıkçası sen geç kalacaksın ama özgüvenle.'::text),
(302895,33655,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Már 10:50 van. Őszintén, te el ... késni, de magabiztosan.'::text,'fogsz'::text,'fogsz'::text,'fog'::text,'Már 10:50 van. Őszintén, te el fogsz késni, de magabiztosan.'::text),
(317721,35303,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Alter, der Hamster futtert gleich ... Snacks, nicht meine.'::text,'seine'::text,'meine'::text,'ihre'::text,'Alter, der Hamster futtert gleich seine Snacks, nicht meine.'::text),
(317725,35303,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бро, хом''як зараз з''їсть ... снеки, а не мої.'::text,'свої'::text,'свої'::text,'свої'::text,'Бро, хом''як зараз з''їсть свої снеки, а не мої.'::text),
(317724,35303,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tío, el hámster va a comerse ... snacks, no los míos.'::text,'sus'::text,'mis'::text,'sus'::text,'Tío, el hámster va a comerse sus snacks, no los míos.'::text),
(317723,35303,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Frérot, le hamster va manger ... snacks, pas les miens.'::text,'ses'::text,'mes'::text,'leurs'::text,'Frérot, le hamster va manger ses snacks, pas les miens.'::text),
(317726,35303,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, hamster ... atıştırmalıklarını yiyecek, benimkileri değil.'::text,'onun'::text,'benim'::text,'onların'::text,'Kanka, hamster onun atıştırmalıklarını yiyecek, benimkileri değil.'::text),
(317727,35303,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, a hörcsög a ... fogja megenni, nem az enyémet.'::text,'nasiját'::text,'nasimat'::text,'nasijukat'::text,'Tesó, a hörcsög a nasiját fogja megenni, nem az enyémet.'::text),
(317757,35307,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'So ... Snacks! Das Sofa ist eine komplette Katastrophe!'::text,'viele'::text,'viel'::text,'irgendwelche'::text,'So viele Snacks! Das Sofa ist eine komplette Katastrophe!'::text),
(317761,35307,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Так ... снеків! Диван — повна катастрофа!'::text,'багато'::text,'багато'::text,'якихось'::text,'Так багато снеків! Диван — повна катастрофа!'::text),
(317760,35307,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡... snacks! ¡El sofá es un desastre total!'::text,'Tantos'::text,'Tanto'::text,'Cualquier'::text,'¡Tantos snacks! ¡El sofá es un desastre total!'::text),
(317759,35307,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... snacks ! Le canapé est une catastrophe totale !'::text,'Tellement de'::text,'Tellement de'::text,'N''importe quels'::text,'Tellement de snacks ! Le canapé est une catastrophe totale !'::text),
(317762,35307,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O kadar ... atıştırmalık! Kanepe tam bir felaket!'::text,'çok'::text,'çok'::text,'herhangi bir'::text,'O kadar çok atıştırmalık! Kanepe tam bir felaket!'::text),
(317763,35307,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Olyan ... nasi! A kanapé teljes katasztrófa!'::text,'sok'::text,'sok'::text,'bármilyen'::text,'Olyan sok nasi! A kanapé teljes katasztrófa!'::text),
(312177,34687,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Eine Frau trägt Rot mit ... Smaragdkette.'::text,'ihrer'::text,'ihrer'::text,'seiner'::text,'Eine Frau trägt Rot mit ihrer Smaragdkette.'::text),
(312181,34687,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Одна жінка носить червоне зі ... смарагдовим намистом.'::text,'своїм'::text,'своїм'::text,'своїм'::text,'Одна жінка носить червоне зі своїм смарагдовим намистом.'::text),
(312180,34687,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Una mujer viste de rojo con ... collar de esmeraldas.'::text,'su'::text,'su'::text,'su'::text,'Una mujer viste de rojo con su collar de esmeraldas.'::text),
(312179,34687,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Une femme porte du rouge avec ... collier d''émeraudes.'::text,'son'::text,'leur'::text,'son'::text,'Une femme porte du rouge avec son collier d''émeraudes.'::text),
(312182,34687,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bir kadın ... zümrüt kolyesiyle kırmızı giyiyor.'::text,'onun'::text,'onların'::text,'onun'::text,'Bir kadın onun zümrüt kolyesiyle kırmızı giyiyor.'::text),
(312183,34687,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Az egyik nő pirosat visel a smaragd ... együtt.'::text,'nyakláncával'::text,'nyakláncukkal'::text,'nyakláncával'::text,'Az egyik nő pirosat visel a smaragd nyakláncával együtt.'::text),
(312204,34690,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Absolut umwerfend! Da ... zwei Frauen in tiefem Rot!'::text,'sind'::text,'ist'::text,'sein'::text,'Absolut umwerfend! Da sind zwei Frauen in tiefem Rot!'::text),
(312208,34690,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Просто приголомшливо! У темно-червоному ... дві жінки!'::text,'є'::text,'є'::text,'бути'::text,'Просто приголомшливо! У темно-червоному є дві жінки!'::text),
(312207,34690,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Absolutamente impresionante! ¡... dos mujeres de rojo intenso!'::text,'Hay'::text,'Hay'::text,'Hay'::text,'¡Absolutamente impresionante! ¡Hay dos mujeres de rojo intenso!'::text),
(312206,34690,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Absolument sublime ! ... deux femmes en rouge profond !'::text,'Il y a'::text,'Il y a'::text,'Il y a'::text,'Absolument sublime ! Il y a deux femmes en rouge profond !'::text),
(312209,34690,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kesinlikle büyüleyici! Koyu kırmızılar içinde iki kadın ...!'::text,'var'::text,'var'::text,'olmak'::text,'Kesinlikle büyüleyici! Koyu kırmızılar içinde iki kadın var!'::text),
(312210,34690,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Lenyűgöző! Két nő ... mélyvörösben!'::text,'van'::text,'van'::text,'lenni'::text,'Lenyűgöző! Két nő van mélyvörösben!'::text),
(307605,34179,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Orange ist ... warme Farbe, und sie trägt sie mit Weiß.'::text,'eine'::text,'eine'::text,'die'::text,'Orange ist eine warme Farbe, und sie trägt sie mit Weiß.'::text),
(307609,34179,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Помаранчевий — це ... теплий колір, і вона носить його з білим.'::text,''::text,NULL::text,NULL::text,'Помаранчевий — це теплий колір, і вона носить його з білим.'::text),
(307608,34179,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El naranja es ... color cálido, y ella lo lleva con blanco.'::text,'un'::text,'un'::text,'el'::text,'El naranja es un color cálido, y ella lo lleva con blanco.'::text),
(307607,34179,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'L''orange est ... couleur chaude, et elle la porte avec du blanc.'::text,'une'::text,'une'::text,'la'::text,'L''orange est une couleur chaude, et elle la porte avec du blanc.'::text),
(307610,34179,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Turuncu ... sıcak renk ve o onu beyazla giyiyor.'::text,'bir'::text,'bir'::text,NULL::text,'Turuncu bir sıcak renk ve o onu beyazla giyiyor.'::text),
(307611,34179,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A narancssárga ... meleg szín, és ő fehérrel viseli.'::text,'egy'::text,'egy'::text,'a'::text,'A narancssárga egy meleg szín, és ő fehérrel viseli.'::text),
(307641,34183,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Rate mal, er hat mir gesagt, in seinem Schrank sind ... orangen Hemden.'::text,'keine'::text,'einige'::text,'viel'::text,'Rate mal, er hat mir gesagt, in seinem Schrank sind keine orangen Hemden.'::text),
(307645,34183,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Уяви, він мені сказав, що в його шафі немає ... помаранчевих сорочок.'::text,'жодних'::text,'якихось'::text,'багато'::text,'Уяви, він мені сказав, що в його шафі немає жодних помаранчевих сорочок.'::text),
(307644,34183,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Adivina, él me dijo que no hay ... camisa naranja en su armario.'::text,'ninguna'::text,'algunas'::text,'mucha'::text,'Adivina, él me dijo que no hay ninguna camisa naranja en su armario.'::text),
(307643,34183,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Devine quoi, il m''a dit qu''il n''y a ... chemise orange dans son armoire.'::text,'aucune'::text,'des'::text,'beaucoup de'::text,'Devine quoi, il m''a dit qu''il n''y a aucune chemise orange dans son armoire.'::text),
(307646,34183,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bil bakalım, o bana dolabında ... turuncu gömlek olmadığını söyledi.'::text,'hiç'::text,'bazı'::text,'çok'::text,'Bil bakalım, o bana dolabında hiç turuncu gömlek olmadığını söyledi.'::text),
(307647,34183,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Képzeld, ő azt mondta, hogy a szekrényében nincs ... narancssárga ing.'::text,'semmilyen'::text,'néhány'::text,'sok'::text,'Képzeld, ő azt mondta, hogy a szekrényében nincs semmilyen narancssárga ing.'::text),
(327306,36368,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bestie, sie hat mir ihren Plan erzählt: Sie ... heute Abend Weiß tragen.'::text,'wird'::text,'wird'::text,NULL::text,'Bestie, sie hat mir ihren Plan erzählt: Sie wird heute Abend Weiß tragen.'::text),
(327310,36368,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Подруго, вона розповіла мені свій план: вона ... носити біле сьогодні ввечері.'::text,'збирається'::text,'буде'::text,NULL::text,'Подруго, вона розповіла мені свій план: вона збирається носити біле сьогодні ввечері.'::text),
